# English versions of the comparison pages (karsilastirma.py). Keys: 'a-b' plant ids.
K_EN = {
'zencefil-zerdecal': dict(baslik='Ginger or turmeric?',
 giris='Ginger and turmeric are two relatives from the same family (Zingiberaceae); in both, the part used is the underground stem (rhizome). They sit side by side in kitchens and on supplement shelves, but their evidence and risks differ.',
 fark=['Ginger’s strongest evidence is for nausea: the European Medicines Agency accepts its use for nausea from motion sickness. Turmeric’s evidence is weaker; there are a few small studies on knee osteoarthritis pain.',
       'Turmeric’s active compound, curcumin, is poorly absorbed; taking it with black pepper and fat increases absorption.',
       'Liver injury has been reported with high-dose turmeric capsules; with ginger, high doses mainly cause heartburn.',
       'Both need care in people on blood thinners and in people with gallstones.'],
 sonuc='For nausea, ginger is the one with evidence. Turmeric is safe as a spice in food; high-dose capsules should not be taken without asking a doctor.'),
'adacayi-dagcayi': dict(baslik='Sage vs mountain tea: what is the difference?',
 giris='In many parts of Anatolia mountain tea is also called “adaçayı” (sage), so the two are often confused. They are plants of different genera: sage is Salvia, mountain tea is Sideritis.',
 fark=['Sage leaves are grey-green and velvety with a sharp smell. Mountain tea is dried with its flowering stems and yellowish flower spikes.',
       'Because sage contains thujone, it should not be drunk for long periods or in large amounts, and is not recommended in pregnancy, breastfeeding or epilepsy. Mountain tea is generally considered safe as a tea.',
       'The European Medicines Agency recognises sage for mouth and throat inflammation, and mountain tea for cough from colds and mild stomach complaints, both as traditional uses.',
       'Some mountain tea species are endemic and over-harvested in the wild; cultivated plants should be preferred.'],
 sonuc='A gargle for the throat is sage’s job. For a tea to drink every day through winter, thujone-free mountain tea is the better fit.'),
'papatya-melisa': dict(baslik='Chamomile or lemon balm? Choosing an evening tea',
 giris='Chamomile and lemon balm are the best-known calming teas drunk in the evening. Both are accepted in Europe for traditional use in mild complaints.',
 fark=['Chamomile is recognised for mild digestive complaints, mouth and throat inflammation and skin irritation; lemon balm for mild stress and sleep problems.',
       'Small studies on anxiety are positive for both, but the evidence is limited.',
       'People allergic to the daisy family should avoid chamomile. Lemon balm needs care in people taking thyroid medication.'],
 sonuc='For restlessness that comes with an upset stomach, chamomile; for the evening after a stressful day, lemon balm. They can also be steeped together.'),
'lavanta-kediotu': dict(baslik='Lavender or valerian? For sleep and anxiety',
 giris='Lavender and valerian are the two herbs most used for sleep and anxiety. The European Medicines Agency recognises both, but their evidence comes in different forms.',
 fark=['For lavender, the strong evidence is for standardised oral lavender oil capsules: they beat placebo for anxiety in several controlled trials. The evidence for lavender tea or scent is not as strong.',
       'Results of sleep studies with valerian root are mixed: some find a small improvement in falling asleep, others find none.',
       'Valerian can cause morning grogginess; it should not be combined with alcohol or sleeping pills, or taken before driving. Lavender capsules can cause burping and nausea.'],
 sonuc='For anxiety, lavender capsules have the stronger evidence. If you struggle to fall asleep, valerian can be tried; neither should be combined with sedatives.'),
'rezene-anason': dict(baslik='Fennel vs anise: what is the difference?',
 giris='Fennel and anise are two similar-smelling seeds from the same family (Apiaceae); both owe their scent to anethole. They are often used together in teas for gas and indigestion.',
 fark=['Fennel seeds are larger and greenish; aniseed is smaller, grey-brown and slightly hairy.',
       'The European Medicines Agency recognises both for mild digestive complaints and gas; fennel also for period pain, anise also for cough from colds.',
       'Because fennel contains estragole, it should not be used long-term by young children or in pregnancy. Concentrated anise oil should not be used in pregnancy or by children.',
       'Both can cause allergy in people allergic to the celery and carrot family.'],
 sonuc='Either is fine for a cup after a meal, and their tastes are very close. Ask a doctor before giving them to babies and young children.'),
'ihlamur-papatya': dict(baslik='Linden or chamomile?',
 giris='Linden and chamomile are the two most popular herbal teas on winter evenings in Türkiye. Both are made by steeping and are generally safe.',
 fark=['Linden is accepted for traditional use in cold symptoms and mild mental stress; there are few clinical studies.',
       'Chamomile is recognised for mild digestive complaints and mouth and throat inflammation; small studies on anxiety are positive.',
       'Chamomile can cause allergy in people allergic to the daisy family; no important risk is known for linden.'],
 sonuc='When you have caught a chill, linden; for an upset stomach, chamomile. Both should be steeped covered, not boiled.'),
'nane-melisa': dict(baslik='Peppermint vs lemon balm: what is the difference?',
 giris='Peppermint and lemon balm belong to the same family (Lamiaceae); their leaves look alike, but their scents are very different: peppermint is cool and sharp, lemon balm smells of lemon.',
 fark=['Peppermint has strong evidence: peppermint oil capsules reduced irritable bowel symptoms in many studies.',
       'Lemon balm is used mostly for mild stress and sleep problems.',
       'Peppermint can worsen reflux, and pure peppermint oil must not be applied to babies’ faces. Lemon balm needs care in people taking thyroid medication.'],
 sonuc='For indigestion and gas, peppermint; for tension, lemon balm.'),
'ekinezya-murver': dict(baslik='Echinacea or elder? For colds',
 giris='Echinacea and elder are two of the best-selling herbal products in cold season. The evidence for both is limited.',
 fark=['Echinacea may slightly prevent or shorten colds, but results are inconsistent.',
       'Elderflower is accepted for traditional use in the early symptoms of a cold; small studies with berry extract are promising but weak.',
       'Raw elderberries, leaves and stems are poisonous; the berries must be cooked. Echinacea needs care in autoimmune disease and in people allergic to the daisy family.'],
 sonuc='Do not expect a big effect from either. If used, start at the first symptoms and use them only briefly.'),
'kekik-adacayi': dict(baslik='Thyme or sage? For cough and sore throat',
 giris='Thyme and sage are the two herbs most often brewed for colds in Anatolia. Both are in the Lamiaceae family and contain strongly scented essential oils.',
 fark=['The European Medicines Agency recognises thyme for productive cough and sage for mouth and throat inflammation, both as traditional uses.',
       'Thyme’s thymol and carvacrol show strong antimicrobial effects in the lab.',
       'Because sage contains thujone, it should not be drunk for long periods or in large amounts. Pure thyme oil burns; it must not be applied to the skin undiluted.'],
 sonuc='For a productive cough, thyme tea; for a sore throat, a sage gargle.'),
'lavanta-karabas': dict(baslik='Lavender vs French lavender (Lavandula stoechas): what is the difference?',
 giris='French lavender (Lavandula stoechas, “karabaş” in Turkish) and true lavender (Lavandula angustifolia) are relatives of the same genus. French lavender grows wild around the Aegean and Mediterranean; what is grown in fields is usually true lavender.',
 fark=['The strong evidence is for true lavender: standardised oil capsules worked for anxiety in several studies. There are very few human studies of French lavender.',
       'Unlike true lavender, French lavender oil contains large amounts of camphor and fenchone; it should not be taken by mouth or applied to children’s faces, because camphor can cause seizures.',
       'French lavender should not be used in pregnancy. True lavender is generally safe but can add to the effect of sedatives.'],
 sonuc='Check which species a “lavender oil” is made from. French lavender tea can be drunk in moderation; its oil should not replace true lavender oil.'),
'kediotu-pasiflora': dict(baslik='Valerian or passionflower?',
 giris='Valerian and passionflower are the two main ingredients of herbal medicines sold in Europe for sleep and anxiety; they are often found in the same tablet.',
 fark=['The European Medicines Agency recognises valerian root for mild nervous tension and sleep problems, and passionflower for mild stress and to help falling asleep.',
       'Studies of passionflower in anxiety and pre-operative nerves are positive but small and short. Results of valerian sleep studies are mixed.',
       'Both can cause drowsiness; they should not be combined with alcohol, sleeping pills or sedatives. Passionflower should not be used in pregnancy.'],
 sonuc='Their evidence is similar and modest. Neither should be taken before driving.'),
'sinameki-keten': dict(baslik='Senna or flaxseed? For constipation',
 giris='Senna and flaxseed work in very different ways. Senna is a stimulant laxative; flaxseed adds bulk to the stool with its fibre and mucilage.',
 fark=['The European Medicines Agency recognises both: senna for short-term treatment of occasional constipation, flaxseed for constipation.',
       'Senna should not be used for more than a week; long-term use causes a lazy bowel and potassium loss. Using it to lose weight is dangerous.',
       'Flaxseed can be used long-term but must always be taken with plenty of water; with too little water it can cause a bowel blockage.'],
 sonuc='For regular use, flaxseed is the suitable one. Senna only briefly and occasionally.'),
# --- 23 November ---
'ginseng-adamotu': dict(baslik='Is ginseng the same as mandrake? Same shape, two plants',
 giris='Both have roots shaped like a human body, which is why both are called “man root” in Turkish folk speech and are often confused. They are completely different plants: ginseng (Panax ginseng) belongs to the ivy family of East Asia, mandrake (Mandragora) to the nightshade family of the Mediterranean. One sits on supplement shelves, the other on lists of poisonous plants.',
 fark=['Ginseng has been used in China and Korea for two thousand years for strength and long life; it contains ginsenosides, and some studies found small effects on blood sugar and immunity. NCCIH says the evidence is limited.', 'The whole mandrake plant is poisonous: its root contains scopolamine and hyoscyamine. That is why it was added to wine as an anaesthetic before surgery in antiquity; the fruit and root can cause hallucinations, heart rhythm disorders and respiratory arrest.', 'Human-shaped roots sold in markets as “aphrodisiacs” are dangerous; preparing or using mandrake is not advised.', 'Ginseng is not harmless either: it can cause insomnia and may interact with blood thinners and diabetes medicines.'],
 sonuc='The Asian ginseng sold as a supplement is not the Mediterranean mandrake. A human-shaped root is not ginseng because of its shape; mandrake should never be taken in any form.'),
'adacayi-akadacayi': dict(baslik='Is sage the same as white sage?',
 giris='Both belong to the genus Salvia and their names are almost the same, but they are used very differently. Anatolian sage (Salvia fruticosa) is brewed and drunk; white sage (Salvia apiana) is the sacred plant that California’s Indigenous peoples burn as incense.',
 fark=['Sage is steeped for 5 minutes as a tea or used as a gargle; the European Medicines Agency recognises it in traditional use for mouth and throat inflammation and excessive sweating.', 'White sage is not prepared for drinking: a bundle of dried leaves is burned and the smoke is wafted. Lab studies show antimicrobial effects; there are no human studies.', 'Because sage contains thujone, it should not be drunk in large amounts for long; it is not advised in pregnancy, breastfeeding or epilepsy. White sage smoke can irritate the airways in closed rooms.', 'Both are under harvesting pressure: most sage sold in Türkiye is wild-collected, and white sage is declining in the wild because of commercial demand.'],
 sonuc='For the throat, the one to drink or gargle is Anatolian sage. White sage is an incense; if you buy it, ask where it comes from, because it is a sacred plant of Indigenous peoples and is declining in the wild.'),
'nane-yarpuz': dict(baslik='Mint or pennyroyal? One scent, two very different risks',
 giris='Pennyroyal is a mint too (Mentha pulegium); it is picked by streams and added to food in place of mint. The two smell alike, but their safety is very different.',
 fark=['Peppermint has some of the strongest evidence in our catalogue: peppermint oil capsules reduced irritable bowel syndrome symptoms compared with placebo in many controlled trials. There are no clinical trials of pennyroyal.', 'Pennyroyal oil is very high in pulegone, which is toxic to the liver and kidneys; deaths have been reported after drinking the oil. Pennyroyal was used throughout history to bring on periods and cause abortion, and this use has killed people.', 'Pennyroyal must never be used in pregnancy; even as a tea it should be drunk only in very small amounts and not for long. Mint is generally safe but may worsen reflux.', 'Pure peppermint oil must not be applied to the faces of babies and small children; it can stop their breathing.'],
 sonuc='For a daily stomach tea or an oil capsule, choose mint. Pennyroyal should stay a small seasoning in food; its essential oil is never swallowed and it is never used in pregnancy.'),
'zakkum-defne': dict(baslik='Oleander or bay laurel? Two trees with look-alike leaves',
 giris='Both are common along the Mediterranean coast and both have long, stiff, glossy green leaves, so the leaves can be confused. One is a kitchen herb; every part of the other is a deadly poisonous ornamental.',
 fark=['Bay leaves go into food and dried leaves are put in cupboards; Hatay’s laurel soap is made from the fruit oil. Kitchen use is safe.', 'Every part of oleander contains cardiac glycosides such as oleandrin that disturb the heart rhythm; even a few leaves are dangerous. Studies of its use for cancer have shown no benefit.', 'Using oleander branches as skewers or barbecue wood can cause poisoning; take care at picnics.', 'Oleander is planted in parks and road verges and has showy pink, white or red flowers; bay flowers are small and yellowish.'],
 sonuc='Never put a leaf from a branch you are unsure of into food or on the barbecue. Oleander must never be prepared or taken; in Türkiye, call the National Poison Information Centre on 114.'),
'cemen-corekotu': dict(baslik='Is fenugreek the same as black seed?',
 giris='The Turkish names sound alike (çemen, çörek otu), but they are two different plants: fenugreek (Trigonella foenum-graecum) is a legume, black seed (Nigella sativa) belongs to the buttercup family. Fenugreek is the base of the spice paste on Turkish pastırma; black seed is sprinkled on pide and cheese.',
 fark=['Fenugreek seeds are yellowish and angular, roasted and ground or soaked; black seeds are small, black and triangular, added whole or cold-pressed for oil.', 'Fenugreek is rich in fibre and saponins; some studies found lower blood sugar, but NCCIH says the evidence is not conclusive. The European Medicines Agency recognises the seed for loss of appetite. Black seed’s active compound is thymoquinone; small studies found slight drops in cholesterol, blood sugar and blood pressure.', 'Fenugreek should not be used in high doses in pregnancy and can cause allergy in people allergic to peanuts or chickpeas.', 'Large amounts of either may strengthen diabetes medicines; fenugreek may also strengthen blood thinners, and black seed oil blood-pressure medicines.'],
 sonuc='In the kitchen, one flavours pastırma and the other pide. If either is taken in medicine-like amounts, people on diabetes medicines should talk to their doctor.'),
'corekotu-kimyon': dict(baslik='Black seed or cumin? The “black cumin” mix-up',
 giris='In many languages black seed is called “black cumin”, which is why it gets confused with cumin. They are from different families: black seed (Nigella sativa) from the buttercups, cumin (Cuminum cyminum) from the carrot family.',
 fark=['Cumin seeds are long, light brown and ridged and flavour meatballs, sausage and bean dishes. Black seeds are small, black and angular and go on bread, buns and cheese.', 'Cumin contains cuminaldehyde, black seed thymoquinone. Cumin has small studies on irritable bowel and weight management; black seed small studies finding slight drops in cholesterol, blood sugar and blood pressure. The evidence is weak for both.', 'Both are safe in food amounts. Above spice amounts, in regular medicine-like use, both may lower blood sugar.', 'Cumin may cause cross-allergy in people allergic to the carrot family (celery, carrot, anise).'],
 sonuc='When a recipe says “black cumin”, it usually means black seed. Cumin is the one to steep for indigestion; black seed is the one sprinkled on bread and cheese.'),
'hatmi-ebegumeci': dict(baslik='Is marshmallow the same as mallow?',
 giris='Both belong to the mallow family (Malvaceae) and are used for the same reason: the mucilage in their tissues coats the throat and stomach. But they are different genera: marshmallow is Althaea officinalis, common mallow Malva sylvestris. Mallow leaves are also eaten as a vegetable.',
 fark=['The European Medicines Agency recognises both in traditional use for mouth and throat irritation and dry cough; with marshmallow the root is used, with mallow the leaves and flowers.', 'Marshmallow root is prepared by soaking in cold water for a few hours, without heat. Mallow can be steeped or soaked; in spring its leaves are sautéed or used for stuffed rolls.', 'In both, the mucilage may delay the absorption of other medicines; leave an hour between them.', 'The English word “marshmallow” comes from this plant: in the 19th century its root mucilage was whipped with sugar to make the first marshmallow sweets.'],
 sonuc='For dry cough and an irritated throat, both do the same job. If you have the root, use marshmallow; if you have leaves and flowers, use mallow. Both are generally safe.'),
'maca-ginseng': dict(baslik='Maca or ginseng? Two roots for strength and energy',
 giris='Both are sold as “roots that give strength”: maca (Lepidium meyenii) is a tuber grown on Peru’s plateaus at 4,000 metres, ginseng (Panax ginseng) the two-thousand-year-old tonic root of East Asia.',
 fark=['Small clinical trials of maca show slight improvements in sexual desire and menopause symptoms; the trials are small and some are funded by manufacturers. Some ginseng studies found small effects on blood sugar and immunity; NCCIH says the evidence is limited.', 'Maca is safe as food; traditionally it is not eaten raw but dried and boiled or eaten as a powder. People with thyroid problems should be careful.', 'Ginseng can cause insomnia and may interact with blood thinners and diabetes medicines.', 'Ginseng is dried or steamed to make “red ginseng” and used as tea or extract.'],
 sonuc='The evidence for both is limited. For someone not on regular medication, maca as a food carries less risk of interactions; anyone on blood thinners or diabetes medicines should not take ginseng without asking their doctor.'),
'tarcin-zencefil': dict(baslik='Cinnamon or ginger? Two warming spices of winter tea',
 giris='Cinnamon is the bark of a tree (Cinnamomum), ginger the underground stem of a plant (Zingiber officinale). Both are said to “warm you up” and to be “good for blood sugar”.',
 fark=['Ginger’s strongest evidence is for nausea: the European Medicines Agency recognises it for preventing motion sickness, and small studies in pregnancy nausea are positive.', 'Cinnamon has many small studies on blood sugar, but the results are inconsistent; NCCIH says there is not enough evidence that it helps any condition.', 'Cassia, the cinnamon most sold in supermarkets, is high in coumarin; eaten by the teaspoon every day it can harm the liver. Ceylon cinnamon contains very little coumarin.', 'Ginger in high doses can cause heartburn; people on blood thinners or with gallstones should ask a doctor before taking supplements.'],
 sonuc='For nausea, ginger is clearly ahead. If you use a lot of cinnamon every day, choose Ceylon cinnamon.'),
'ashwagandha-ginseng': dict(baslik='Ashwagandha or ginseng? Two roots for stress and energy',
 giris='Ashwagandha (Withania somnifera) is the root of Indian Ayurveda, ginseng (Panax ginseng) of Chinese and Korean medicine. Both are sold today as “adaptogens”.',
 fark=['For ashwagandha, a few small, short controlled trials report lower stress and anxiety scores; NCCIH stresses that its long-term safety is unknown.', 'Some ginseng studies found small effects on blood sugar and immunity; the evidence is limited.', 'Ashwagandha has been linked to cases of liver injury, may raise thyroid hormones and carries a risk of miscarriage; some European countries have restricted its supplements.', 'Ginseng can cause insomnia and may interact with blood thinners and diabetes medicines.'],
 sonuc='Ashwagandha sits on the calming side, ginseng on the stimulating side. Anyone on thyroid medication or pregnant should not take ashwagandha, and anyone on blood thinners should not take ginseng, without asking a doctor.'),
'kusburnu-kizilcik': dict(baslik='Rose hip or cornelian cherry? Two sour winter fruits of Anatolia',
 giris='Both are red, sour fruits picked in autumn and made into jams, sherbets and teas. Rose hip (Rosa canina) is from the rose family, cornelian cherry (Cornus mas) from the dogwood family.',
 fark=['Fresh rose hips are very rich in vitamin C; a few clinical trials with rose hip powder looked at knee osteoarthritis pain.', 'Cornelian cherry is rich in anthocyanins and vitamin C; small studies report slight improvements in blood lipids.', 'The hairs around rose hip seeds irritate the mouth and gut; always strain.', 'Cornelian cherry stones are hard and dangerous for small children; its sourness can worsen reflux.'],
 sonuc='Both are safe and local foods. Remember to remove the rose hip hairs and the cornelian cherry stones.'),
'nar-hibiskus': dict(baslik='Pomegranate or hibiscus? Two red drinks for blood pressure',
 giris='Pomegranate juice and hibiscus tea are both deep red and sour, and both are said to “lower blood pressure”.',
 fark=['Several controlled trials and meta-analyses show hibiscus tea slightly lowers blood pressure; the trials are small and short.', 'Small studies also report pomegranate juice slightly lowering blood pressure; claims such as prostate cancer lack evidence.', 'Hibiscus may strengthen blood-pressure medicines; do not drink a lot in pregnancy.', 'Pomegranate juice may affect how some medicines are broken down; the peel and root bark are toxic in high doses.'],
 sonuc='If you take blood-pressure medicine, tell your doctor before drinking either regularly; the evidence for hibiscus is slightly stronger.'),
'sumak-nar': dict(baslik='Sumac or pomegranate molasses? The two sours of the kitchen',
 giris='Both add sourness to salads and kebabs and are staples of south-eastern Turkish cooking. Sumac (Rhus coriaria) is the dried fruit of a shrub; pomegranate molasses is reduced pomegranate (Punica granatum) juice.',
 fark=['Sumac is rich in tannins and organic acids; small clinical studies report slight drops in blood sugar and cholesterol.', 'Pomegranate is rich in polyphenols; small studies report pomegranate juice slightly lowering blood pressure.', 'Sumac may cause cross-allergy in people allergic to cashews or pistachios.', 'Much “pomegranate molasses” on the market is a pomegranate-flavoured sauce of sugar, acid and colouring; choose one whose label lists only pomegranate.'],
 sonuc='Both are safe as food. Buy unsalted sumac and pure pomegranate molasses.'),
'safran-zerdecal': dict(baslik='Saffron or turmeric? Two spices that turn food yellow',
 giris='Saffron (Crocus sativus) is the dried stigmas of a crocus, turmeric (Curcuma longa) the powdered root of a ginger relative. One is the world’s most expensive spice, the other one of the cheapest.',
 fark=['Meta-analyses of small controlled trials show saffron beats placebo in mild to moderate depression; most trials are short and from a single country.', 'Curcumin from turmeric helped knee osteoarthritis pain in some small studies; NCCIH says the evidence for most claims is weak and curcumin is poorly absorbed.', 'Saffron is toxic above 5 g a day and high doses carry a risk of miscarriage; cheap “saffron” is usually safflower or dyed fibre.', 'High-dose turmeric capsules have been linked to cases of liver injury; turmeric may interact with blood thinners, and people with gallstones should be careful.'],
 sonuc='Both are safe in food. Beware fake saffron: real threads colour water yellow slowly.'),
'ayahuasca-sanpedro': dict(baslik='Ayahuasca or San Pedro? Two ceremonies of the Amazon and the Andes',
 giris='Ayahuasca is an Amazonian brew of a vine (Banisteriopsis caapi), usually cooked with chacruna leaves; San Pedro (Echinopsis pachanoi) is a mescaline-containing cactus of the Andes. Both are central to Indigenous healing ceremonies.',
 fark=['The ayahuasca vine contains harmala alkaloids that block MAO-A, which makes the DMT in chacruna active when swallowed. San Pedro’s effect comes from mescaline.', 'Small clinical studies of ayahuasca in depression are promising but early; mescaline has been studied far less than psilocybin and LSD.', 'Ayahuasca can interact fatally with antidepressants and some migraine and heart medicines; deaths and abuse have been reported at unsupervised retreats.', 'San Pedro causes severe nausea, vomiting and a racing heart; it is dangerous for people with heart disease or a history of psychosis.'],
 sonuc='Neither is legal in Türkiye, and neither is something to try at home. This page is for cultural and scientific information.'),
'tatula-banotu': dict(baslik='Jimsonweed or henbane? Two poisonous nightshades',
 giris='Jimsonweed (Datura stramonium) and henbane (Hyoscyamus niger) grow on roadsides and waste ground across Anatolia and carry the same poison. Jimsonweed has a spiny fruit and large white trumpet flowers; henbane has pale yellow flowers with purple veins.',
 fark=['Both contain tropane alkaloids such as atropine, hyoscyamine and scopolamine; their effects are the same.', 'Symptoms: dry mouth, high fever, dilated pupils, hallucinations, racing heart, coma.', 'Jimsonweed has killed teenagers who tried it as a “natural drug”; henbane has poisoned people who picked and ate it by mistake.', 'These alkaloids are the source of today’s medicines for nausea, cramps and eye examinations; but in the plant itself the dose cannot be controlled.'],
 sonuc='Neither has any home use. If you suspect poisoning in Türkiye, call the National Poison Information Centre on 114.'),
# --- 23 November, evening: remaining comparisons ---
'geven-cingeveni': dict(baslik='Anatolian milkvetch or Chinese astragalus? One name, two plants',
 giris='In Turkish both are called “geven”, and the confusion has reached official texts: the species registered as “geven” on TİTCK’s medicinal plant list is Chinese medicine’s Astragalus membranaceus. Anatolia’s geven is the spiny cushion plant of the steppe (A. gummifer, A. longifolius, A. muschianus), and even the part used is different.',
 fark=['Different parts: in Anatolia, the gum that oozes when the stem is cut (gum tragacanth); in China, the dried root.', 'Only the Chinese species has official monographs (TİTCK and WHO, for A. membranaceus / A. mongholicus). Anatolian species have none. The WHO monograph also says “none” under uses supported by clinical data.', 'Tragacanth’s proven role is a material property, not a drug effect — a thickener and suspending agent, the food additive E 413. Chinese astragalus claims immune and fatigue effects, with limited evidence.', 'Warnings do not transfer. Chinese astragalus stimulates immunity, so it is not used in autoimmune diseases such as MS, lupus or rheumatoid arthritis and interacts with immunosuppressants and anticoagulants. Tragacanth has its own warning: it is not swallowed dry, as it swells in water and can cause blockage.', 'Türkiye is one of the world’s centres of Astragalus diversity, with over four hundred species, many found nowhere else. Yet “astragalus” supplements on the market are none of them, but an imported Chinese root.'],
 sonuc='If you take an “astragalus” supplement, it is the Chinese root, not the spiny steppe cushion. Check the Latin name: A. membranaceus or A. mongholicus means Chinese astragalus. There is no clinical evidence for medicinal use of Anatolian species, and tragacanth is an excipient, not a medicine.'),
'karahindiba-hindiba': dict(baslik='Is dandelion the same as chicory?',
 giris='One letter apart in Turkish (karahindiba, hindiba), two different plants: dandelion is Taraxacum officinale, chicory Cichorium intybus. Both are in the daisy family, both have edible leaves and bitter roots, but their monographs and warnings differ.',
 fark=['The European Medicines Agency recognises dandelion leaf as a mild diuretic and the root for mild digestive complaints. Chicory’s only monograph indication is mild digestive complaints and temporary loss of appetite.', 'Chicory has pooled evidence outside the monograph: a meta-analysis of five studies in 197 people with fatty liver disease found falls in two liver enzymes. Dandelion has very few human studies.', 'Chicory should not be used with gallstones and should be stopped two weeks before surgery because it may lower blood sugar (TİTCK). Dandelion should not be used with blocked bile ducts and may strengthen diuretics.', 'Dandelion root is roasted and drunk like coffee; chicory root is well known as a coffee additive in the same way.'],
 sonuc='Dandelion is the spring salad green known as a diuretic; chicory has a monograph as a bitter digestive. Anyone with gallstones should ask a doctor about either.'),
'papatya-romenpapatyasi': dict(baslik='Chamomile or Roman chamomile?',
 giris='In Turkey “papatya” means Matricaria chamomilla. Roman chamomile is a different genus, Chamaemelum nobile, native to western Europe and not wild in Türkiye. Both can be sold as “chamomile” in tea packets.',
 fark=['The European Medicines Agency recognises chamomile for mild digestive complaints, mouth and throat inflammation and skin irritation. Roman chamomile’s only indication is mild, spasmodic gastrointestinal complaints including bloating and wind; skin and mouth use are not in its monograph.', 'TİTCK’s Roman chamomile monograph says it “should not be used together” with three groups of medicines — much stronger wording than chamomile’s warning.', 'Both may cause allergy in people allergic to the daisy family; chamomile needs care in people on blood thinners.', 'Small clinical studies of chamomile in anxiety are positive; Roman chamomile has no clinical trial in its monograph indication.'],
 sonuc='For the stomach and throat, the familiar evening tea is chamomile. Roman chamomile should not be drunk by someone on regular medication without asking a doctor; the Latin name on the pack is the easiest way to tell them apart.'),
'kantaron-kirmizikantaron': dict(baslik='Is St John’s wort the same as centaury?',
 giris='In Turkish, “kantaron” names two plants that are not even related: yellow kantaron, St John’s wort (Hypericum perforatum, Hypericaceae), and red kantaron, centaury (Centaurium erythraea, Gentianaceae). Adding to the confusion, the red “kantaron oil” is made from St John’s wort.',
 fark=['St John’s wort flowers are left in olive oil in the sun for 4–6 weeks to make red kantaron oil. Centaury itself is a pink-flowered herb used for its bitter taste as a digestive.', 'St John’s wort has strong evidence: a Cochrane review found standard extracts better than placebo in mild to moderate depression. Centaury has no clinical studies in humans; its monograph recognises it in traditional use for mild indigestion and loss of appetite.', 'St John’s wort weakens many medicines: the contraceptive pill, blood thinners, some heart and transplant drugs; with antidepressants it can cause serotonin syndrome.', 'Centaury is contraindicated in peptic ulcer and is not used under 18.'],
 sonuc='When you ask a herbalist for “kantaron”, say which one by its Latin name. Anyone on medication should not take St John’s wort without asking their doctor; anyone with an ulcer should avoid centaury.'),
'cay-mate': dict(baslik='Tea or yerba mate? Two caffeinated leaves',
 giris='Tea (Camellia sinensis) and mate (Ilex paraguariensis) are the daily caffeine of two corners of the world: one of Asia and Anatolia, the other of South America. Both are brewed from the leaf.',
 fark=['Tea contains caffeine, L-theanine and catechins; in observational studies regular tea drinking is associated with lower cardiovascular risk. A meta-analysis of 13 randomised trials of mate found lower blood sugar in people with prediabetes, but the finding rests on few studies.', 'The European Medicines Agency recognises mate in traditional use for fatigue and weakness and mild urinary complaints. Mate is not recommended before bed; it can disturb sleep.', 'Mate should not be used with stomach or intestinal ulcers, heart conditions such as high blood pressure and arrhythmia, or an overactive thyroid (TİTCK). Tea is safe as a drink; high-dose green tea extract capsules have been linked to liver injury.', 'For both, cancer risk comes less from the drink than from its temperature: very hot drinks are a risk for the oesophagus.'],
 sonuc='Both are fine as daily drinks; mate is not suitable for someone with high blood pressure, arrhythmia or an ulcer. Whichever you drink, let it cool a little.'),
'goji-kusburnu': dict(baslik='Goji or rose hip? Two red fruits, two different stories',
 giris='One is sold at a premium from China as a “superfruit”, the other grows on every Anatolian hillside. Goji (Lycium barbarum) is a nightshade; rose hip (Rosa canina) is in the rose family.',
 fark=['Fresh rose hips are very rich in vitamin C, but drying and boiling destroy most of it. Goji has less vitamin C; what stands out are its polysaccharides and carotenoids.', 'A few clinical trials with rose hip powder report less pain in knee osteoarthritis. Goji studies are small and mostly about general wellbeing and eye health.', 'Goji has been linked to bleeding and raised INR in people on warfarin; no such interaction has been reported for rose hip.', 'The hairs around rose hip seeds irritate the mouth and gut, so teas and jams are always strained. Goji is eaten as it is.'],
 sonuc='For vitamin C, fresh rose hips or a well-made rose hip jam are a cheaper, local option. Anyone on warfarin should avoid goji.'),
'dagcayi-ihlamur': dict(baslik='Mountain tea or linden? Two classic winter teas',
 giris='Both are the first teas Anatolians reach for with a cold. Mountain tea (Sideritis species) is a mint-family plant of rocky mountain slopes; linden (Tilia) is the flower of a tree.',
 fark=['The European Medicines Agency recognises both in traditional use: mountain tea for cough with colds and mild stomach complaints, linden for cold symptoms and mild mental stress. Both have few clinical studies.', 'Linden has no known drug interactions; no serious interaction has been reported for mountain tea either.', 'For both, there are not enough data in pregnancy and breastfeeding.', 'Some mountain tea species are endemic and over-collected in the wild; buying cultivated product protects nature. Linden is steeped, not boiled; boiling makes it bitter.'],
 sonuc='If cough and indigestion come first, mountain tea; for a restless evening and a mild chill, linden. They can be brewed together.'),
'kakule-karanfil': dict(baslik='Cardamom or clove? Two scents of coffee and tea',
 giris='Cardamom (Elettaria cardamomum) is a seed pod from the ginger family; clove (Syzygium aromaticum) is a dried flower bud from the myrtle family. Both are used in Turkish coffee and winter teas.',
 fark=['Eugenol in clove oil has been used for centuries in dentistry as a local painkiller; the European Medicines Agency recognises clove oil for toothache in traditional use. Cardamom has no such medicinal use.', 'Meta-analyses find cardamom powder supplements may slightly lower some inflammation markers and blood pressure; cholesterol and blood sugar results are inconsistent.', 'Both are safe as spices. But clove essential oil, if swallowed — especially by children — can cause liver damage and seizures, and may interact with blood thinners.', 'Cardamom goes into coffee as whole or crushed pods; a few whole cloves go into tea and desserts.'],
 sonuc='Both can be used freely in the kitchen. The difference is the essential oil: keep the clove oil bottle out of children’s reach.'),
'ginkgo-gotukola': dict(baslik='Ginkgo or gotu kola? Two plants sold for “memory”',
 giris='Ginkgo (Ginkgo biloba) is one of the oldest living tree species; gotu kola (Centella asiatica) is a creeping herb of tropical Asia. Both are marketed as memory supplements.',
 fark=['The European Medicines Agency recognises standardised ginkgo leaf extract for mild age-related cognitive decline; but a large US trial (GEM) showed ginkgo did not prevent dementia in older people.', 'Gotu kola has no strong evidence for memory; the European Medicines Agency recognises it only for helping small wounds heal, applied to the skin.', 'Ginkgo can increase bleeding risk and should be stopped before surgery; its seeds are poisonous.', 'Cases of liver injury have been reported with long-term oral gotu kola; people with liver disease, pregnant and breastfeeding women should not use it.'],
 sonuc='Neither has solid evidence for memory. Ginkgo is risky for someone on blood thinners, gotu kola for someone with liver problems.'),
'sibiryaginsengi-ginseng': dict(baslik='Is Siberian ginseng really ginseng?',
 giris='No. Siberian ginseng (Eleutherococcus senticosus) and Asian ginseng (Panax ginseng) are in the same family (Araliaceae) but different genera. The name comes from its sale as a cheap substitute for ginseng in the Soviet era.',
 fark=['Their chemistry differs: Panax ginseng contains ginsenosides; Siberian ginseng has none — its active compounds are eleutherosides.', 'The European Medicines Agency and TİTCK recognise Siberian ginseng in traditional use for fatigue and weakness; but there is no single-ingredient clinical trial of the root in this indication.', 'The side effects listed in its monographs are insomnia, headache, palpitations and tachycardia.', 'Panax ginseng can also cause insomnia and may interact with blood thinners and diabetes medicines.'],
 sonuc='If the label just says “ginseng”, check the Latin name: Panax or Eleutherococcus? They are not the same product, and a study of one is not evidence for the other.'),
'kediotu-serbetciotu': dict(baslik='Valerian or hops? Two bitter teas for sleep',
 giris='Valerian (Valeriana officinalis) is a root; hops (Humulus lupulus) are the female cones that make beer bitter. They are usually found together in sleep supplements.',
 fark=['The European Medicines Agency recognises valerian for mild nervous tension and sleep problems at “well-established use” level, hops only in traditional use.', 'Clinical studies of hops have mostly tested them with valerian, not alone; little is known of their effect on their own.', 'Hops contain oestrogen-like substances; people with hormone-sensitive conditions such as breast, uterine or ovarian cancer should not use them.', 'Both cause drowsiness; do not combine with alcohol, sleeping pills or sedatives, and do not drive afterwards.'],
 sonuc='If you choose one plant, valerian has the stronger evidence. With a hormone-sensitive condition, avoid blends containing hops.'),
'melisa-limonverbena': dict(baslik='Lemon balm or lemon verbena? Two lemon-scented calmers',
 giris='Both smell of lemon and are often confused. Lemon balm (Melissa officinalis) is a mint-family plant; lemon verbena (Aloysia citrodora) is a shrub of the verbena family.',
 fark=['The European Medicines Agency recognises lemon balm in traditional use for mild stress, sleep problems and mild digestive complaints; small studies report improved anxiety and sleep.', 'Lemon verbena has a 71-person double-blind trial for sleep, published in 2024.', 'Lemon balm needs care in people on thyroid medication.', 'Lemon verbena may impair driving and using machines; people allergic to the verbena family should not use it.'],
 sonuc='Lemon balm for mild daytime tension, lemon verbena for sleep at night; do not drive after lemon verbena.'),
'kantaron-pasiflora': dict(baslik='St John’s wort or passionflower? Two plants for mood, two different risks',
 giris='St John’s wort (Hypericum perforatum) and passionflower (Passiflora incarnata) are both known as “good for the nerves”. But one is as potent as a drug, the other a mild calmer.',
 fark=['According to a Cochrane review, standard St John’s wort extracts beat placebo in mild and moderate depression and are close to some antidepressants; in Germany it is used as a medicine.', 'The European Medicines Agency recognises passionflower in traditional use for mild stress and to help falling asleep; studies on anxiety are positive but small.', 'St John’s wort weakens many medicines: the contraceptive pill, blood thinners, some heart and transplant drugs. With antidepressants it can cause serotonin syndrome.', 'Passionflower causes drowsiness; it is not used in pregnancy, and its effect adds up with alcohol and sedatives.'],
 sonuc='Depression is not managed with a plant alone. Anyone on regular medication — especially the contraceptive pill — must never take St John’s wort without asking a doctor.'),
'aloe-hamamelis': dict(baslik='Aloe vera or witch hazel? Two plants for the skin',
 giris='Aloe vera gel and witch hazel (Hamamelis virginiana) water sit side by side on pharmacy shelves. One soothes, the other tightens.',
 fark=['Small studies suggest aloe gel may speed healing of mild burns and sunburn.', 'The European Medicines Agency recognises witch hazel in traditional use for mild skin inflammation, small wounds and the itching and burning of haemorrhoids; its effect comes from astringent tannins.', 'If aloe leaf latex rather than gel is swallowed, it is a strong laxative: diarrhoea, cramps and potassium loss; it is not taken by mouth in pregnancy.', 'Most witch hazel water contains alcohol and can dry the skin; it is not recommended by mouth.'],
 sonuc='Aloe gel for sunburn and dry, irritated skin; witch hazel for oily skin and small inflammations. Both are for the skin only.'),
'cayagaci-okaliptus': dict(baslik='Tea tree oil or eucalyptus oil? Two essential oils of one family',
 giris='Both are essential oils distilled from the leaves of Australian trees in the myrtle family. Tea tree (Melaleuca alternifolia) is used for the skin, eucalyptus (Eucalyptus globulus) for breathing.',
 fark=['Tea tree oil has a 2026 meta-analysis pooling seven clinical trials in acne.', 'The European Medicines Agency recognises eucalyptus oil in traditional use for relieving cough with colds.', 'Tea tree oil is not swallowed or inhaled and should not be applied undiluted.', 'Even a few millilitres of eucalyptus oil swallowed can cause seizures and loss of consciousness in children; it is not applied to babies’ faces or noses, and steam can trigger attacks in people with asthma.'],
 sonuc='Neither is drunk, and both belong out of children’s reach. Diluted tea tree oil for spots, eucalyptus for an adult chest rub.'),
'sarimsak-sogan': dict(baslik='Garlic or onion? The kitchen’s two alliums',
 giris='Garlic (Allium sativum) and onion (Allium cepa) are two vegetables of the same genus, carrying relatives of the same sulphur compounds.',
 fark=['The evidence for garlic is stronger: meta-analyses show garlic preparations slightly lower blood pressure and cholesterol; NCCIH notes the effect is small.', 'Onion has a 2023 meta-analysis of 14 randomised trials on metabolic measures; its effects are small too.', 'High-dose garlic may strengthen blood thinners; supplements should be stopped before surgery.', 'The only known barrier to onion is onion allergy.'],
 sonuc='Both can be used generously in cooking. Garlic’s allicin forms fully if you wait ten minutes after crushing.'),
'yildizanason-anason': dict(baslik='Is star anise the same as anise?',
 giris='No. Their scent comes from the same compound (anethole), but they are two different plants: anise (Pimpinella anisum) is a small seed of the carrot family; star anise (Illicium verum) is the star-shaped fruit of a tree grown in China.',
 fark=['The European Medicines Agency recognises anise in traditional use for mild indigestion, bloating and cough with colds.', 'Star anise’s biggest risk is mix-ups: poisonous Japanese star anise (Illicium anisatum) looks almost the same and has been mixed in on the market; seizures and vomiting have been reported in babies after star anise teas.', 'Anise may cause allergy in people allergic to the carrot family (celery, fennel); its essential oil is not used in pregnancy or in children.', 'Star anise is a source of shikimic acid, the raw material of a flu drug; but the spice itself has not been shown to affect flu.'],
 sonuc='Do not give star anise tea to babies or small children. Ask a doctor before giving a baby any tea for colic.'),
'kimyon-frenkkimyonu': dict(baslik='Is cumin the same as caraway?',
 giris='No. Both are similar crescent-shaped seeds of the carrot family, but they taste different. Cumin (Cuminum cyminum) is the spice of meatballs; caraway (Carum carvi) the spice of rye bread and cabbage.',
 fark=['Caraway’s strongest evidence is in combination with peppermint oil: a 2023 Cochrane review looked at the mix in functional dyspepsia. The European Medicines Agency recognises caraway for bloating and wind.', 'Cumin has small studies in irritable bowel syndrome and weight management; the evidence is weak.', 'Caraway essential oil is not taken directly by mouth; people with liver disease or gallstones should not use it.', 'Cumin is safe in spice amounts; the safety of higher, regular use is unknown, and it may lower blood sugar.'],
 sonuc='For bloating, a cup of caraway tea after a meal is closer to the evidence. Do not swap one for the other in a recipe; the taste is completely different.'),
'guarana-kola': dict(baslik='Guaraná or kola? Two caffeinated seeds',
 giris='Guaraná (Paullinia cupana) is the caffeinated seed of the Amazon, kola (Cola nitida, C. acuminata) of West Africa. Kola gave its name to the soft drink; guaraná is found today in energy drinks.',
 fark=['Guaraná seeds contain a higher proportion of caffeine than coffee beans.', 'The European Medicines Agency and TİTCK recognise kola in traditional use for temporary fatigue and weakness; it has no stand-alone clinical trial.', 'Both can be a problem with stomach ulcers, high blood pressure, heart rhythm disorders and an overactive thyroid — because of the caffeine.', 'In energy drinks guaraná may be combined with other stimulants; together with separately listed caffeine, the total can be higher than expected.'],
 sonuc='In both, the effect comes from caffeine. Count the daily total with coffee and tea; do not take them before bed.'),
'baldiran-dereotu': dict(baslik='Poison hemlock or dill? A deadly mix-up',
 giris='Poison hemlock (Conium maculatum) and dill (Anethum graveolens) are in the same family and look alike, with umbrella-shaped flowers and fine leaves. Hemlock is the poison that killed Socrates.',
 fark=['Hemlock’s stem is smooth with purple-red blotches and smells like mouse urine when crushed. Dill’s stem is unspotted and its smell is familiar and pleasant.', 'Every part of hemlock is poisonous: burning in the mouth, nausea and paralysis that climbs from the legs; breathing can stop.', 'Hemlock is most often picked by mistake for parsley or wild carrot.', 'Dill is safe as food; but the WHO monograph says fruit extracts should not be used in pregnancy and breastfeeding.'],
 sonuc='If you cannot identify an umbrella-flowered plant in the wild with certainty, do not pick it. In Türkiye, call 114 if poisoning is suspected.'),
'yuksukotu-karakafesotu': dict(baslik='Foxglove or comfrey? When the leaves get mixed up',
 giris='Before flowering, foxglove (Digitalis) forms a leaf rosette resembling comfrey (Symphytum officinale). Foxglove brewed as “comfrey tea” has killed people.',
 fark=['Foxglove contains cardiac glycosides: nausea, vomiting, yellow-green vision and fatal heart rhythm disorders. The therapeutic and toxic doses are very close.', 'Comfrey leaves are rough with stiff hairs; foxglove leaves are softer and velvety.', 'Comfrey is not safe either: the root is not taken by mouth, because its pyrrolizidine alkaloids damage the liver.', 'Comfrey ointment is applied briefly to the skin for back and joint pain; there are small studies of this use.'],
 sonuc='Neither is a tea plant. The heart drug digoxin comes from foxglove; the plant itself is never used.'),
'ekinezya-andrographis': dict(baslik='Echinacea or andrographis? Two plants for colds',
 giris='Echinacea (Echinacea purpurea) is a purple-flowered daisy of North America; andrographis (Andrographis paniculata) is a very bitter herb of Indian and Chinese medicine. Both are sold for colds.',
 fark=['The European Medicines Agency recognises echinacea herb for short-term treatment of colds; according to NCCIH it may have a small effect but results are inconsistent.', 'Andrographis has a 2017 meta-analysis in acute respiratory infections, but no European monograph.', 'Echinacea may cause allergy in people allergic to the daisy family; people with autoimmune disease should be careful.', 'Andrographis is very bitter; it can cause stomach upset and taste changes and is not used in pregnancy or breastfeeding.'],
 sonuc='The effect of both is small. If fever lasts more than three days or you become short of breath, see a doctor rather than relying on a plant.'),
'anason-baldiran': dict(baslik='Anise or poison hemlock? A deadly umbrella mix-up',
 giris='Anise (Pimpinella anisum) and poison hemlock (Conium maculatum) are in the same family, both with white umbrella flowers. One is a tea and raki seed, the other the poison that killed Socrates.',
 fark=['Anise is sold as seed and grown as a crop; hemlock grows wild on roadsides and riverbanks.', 'Hemlock’s stem is smooth, hollow and blotched dark purple; its crushed leaf smells like cat urine. Anise has a distinct, sweet anethole scent.', 'Every part of hemlock is poisonous: burning mouth, nausea and paralysis climbing from the legs; breathing can stop.', 'Anise has wild Pimpinella relatives too, and they are not anise.'],
 sonuc='Buy anise only from a shop. No white umbrella-flowered plant picked in the wild is used as anise. In Türkiye, call 114 if poisoning is suspected.'),
'baldiran-rezene': dict(baslik='Poison hemlock or fennel? Don’t pick the one without the scent',
 giris='Fennel (Foeniculum vulgare) also grows wild in the Aegean and is picked and eaten. Poison hemlock (Conium maculatum), from the same family, is deadly and grows in similar places.',
 fark=['Fennel has yellow umbrella flowers and fine, hair-like leaves, and the whole plant smells strongly of anise. Hemlock’s flowers are white.', 'Hemlock’s stem is smooth, hollow and purple-blotched and gives off a foul, cat-urine smell when crushed.', 'Fennel seed and tea are generally safe; because of estragole, long-term use is not advised in small children or pregnancy.', 'The commonest cause of hemlock poisoning is picking it in mistake for an edible umbellifer.',
       'Hemlock poisoning starts with burning in the mouth, nausea and muscle weakness, then a paralysis that climbs from the legs; breathing can stop.'],
 sonuc='Never pick an umbrella-flowered plant without the anise smell as fennel. If you are not sure, do not pick it at all.'),
'baldiran-frenkkimyonu': dict(baslik='Poison hemlock or caraway? Don’t gather the seeds in the wild',
 giris='Caraway (Carum carvi) is an umbellifer used in cooking and tea. Poison hemlock (Conium maculatum), from the same family, is deadly, and its fruits and leaves can look alike.',
 fark=['Caraway is sold as dried fruit; seed from a wild umbellifer is never used in its place.', 'Hemlock’s spotted, smooth stem and foul smell set it apart, but telling them apart is a job for an expert.', 'Caraway is generally safe as a tea; its essential oil is not taken by mouth, and it is not used in liver or bile disease.', 'Every part of hemlock is poisonous; it causes paralysis climbing from the legs and respiratory arrest.'],
 sonuc='Do not gather umbellifer fruits or roots in the wild. Buy caraway packaged.'),
'baldiran-selamotu': dict(baslik='Poison hemlock or lovage? Their roots look alike',
 giris='Lovage (Levisticum officinale) root is an umbellifer used for the urinary tract. Poison hemlock (Conium maculatum), from the same family, is deadly, and the roots can be confused.',
 fark=['Lovage is grown in gardens and smells of celery; the name “wild celery” is also used for other plants, which adds to the confusion.', 'Hemlock has a spotted, smooth stem and a foul smell; as roots they are very hard to tell apart.', 'Lovage is not used with oedema or blood-pressure problems; fever, painful urination or blood in the urine need a doctor, not a tea.', 'Every part of hemlock, including the root, is poisonous.',
       'Hemlock poisoning starts with burning in the mouth and muscle weakness, then a paralysis that climbs from the legs.',
       'Lovage is also not recommended in kidney inflammation, impaired kidney function or feverish illness.'],
 sonuc='Umbellifer roots are not gathered in the wild. Buy lovage root only labelled, from a pharmacy or herbalist.'),
'angelika-baldiran': dict(baslik='Angelica or poison hemlock? Two large umbellifers',
 giris='Angelica (Angelica archangelica) root is a large umbellifer used for digestion. Poison hemlock (Conium) and water hemlock (Cicuta) are in the same family and deadly.',
 fark=['Angelica’s wild relatives (wild angelica, Chinese angelica) are separate species with separate monographs.', 'Hemlock’s stem is smooth, hollow and purple-blotched and smells foul when crushed.', 'Angelica root is phototoxic: avoid sun and sunbeds while taking it; it is not used in pregnancy.', 'Every part of hemlock is poisonous; it can cause respiratory paralysis.'],
 sonuc='Wild umbellifers are not gathered. Use angelica only as a labelled product.'),
'baldiran-kisnis': dict(baslik='Poison hemlock or coriander? The leaves can be confused',
 giris='Coriander (Coriandrum sativum) is an umbellifer whose leaves and fruits are eaten. Poison hemlock (Conium maculatum), from the same family, is deadly.',
 fark=['Coriander is grown in gardens and fields and has its own sharp smell.', 'Hemlock grows wild; its stem is purple-blotched and smooth and smells foul when crushed.', 'Coriander fruit may increase sensitivity to sunlight and may lower blood sugar and blood pressure.', 'Every part of hemlock is poisonous.'],
 sonuc='Use coriander only from cultivated plants; umbellifer seeds are not gathered in the wild.'),
'gucigdemi-safran': dict(baslik='Autumn crocus or saffron? Two purple flowers of autumn',
 giris='Saffron (Crocus sativus) and autumn crocus (Colchicum) are very similar purple flowers that bloom in autumn. One is the world’s most expensive spice, the other deadly poisonous.',
 fark=['An easy difference to count: autumn crocus flowers have 6 stamens, saffron and other Crocus species have 3.', 'Every part of autumn crocus contains colchicine and is deadly; symptoms begin hours later.', 'Saffron is safe in food amounts; above 5 g a day it is toxic.', 'Autumn crocus poisonings happen when the flower is taken for saffron or the leaf for wild garlic.'],
 sonuc='Do not gather “saffron” in the wild. Buy saffron only as threads from a trusted seller.'),
'gucigdemi-sarimsak': dict(baslik='Autumn crocus or wild garlic? Leaf mix-ups in spring',
 giris='The broad leaves autumn crocus (Colchicum) puts out in spring look like wild garlic and leek leaves. Garlic (Allium sativum) is a kitchen staple.',
 fark=['Garlic and wild garlic leaves smell clearly of garlic when crushed; autumn crocus leaves do not.', 'Every part of autumn crocus is deadly; symptoms start hours later, so it is noticed late.', 'Poisonous lily-of-the-valley leaves have also caused poisonings when taken for wild garlic.', 'Garlic is safe as food; high-dose supplements may strengthen blood thinners.'],
 sonuc='If you gather wild garlic, smell every leaf one by one; if unsure, do not gather. In Türkiye, call 114.'),
'guzelavratotu-yabanmersini': dict(baslik='How to tell deadly nightshade from bilberry',
 giris='Bilberry (Vaccinium myrtillus) is a small, edible purple forest berry. The glossy black berries of deadly nightshade (Atropa belladonna) look like it and are deadly.',
 fark=['Deadly nightshade berries are single, large and glossy black, with a star-shaped green calyx behind them. Bilberries are small, matt blue-purple and purple inside.', 'Every part of deadly nightshade is deadly; the berry is the greatest danger for children.', 'Symptoms: dry mouth, dilated pupils, hot flushed skin, palpitations, hallucinations, seizures, coma.', 'Bilberry is a fruit with no serious safety concern in its monographs.'],
 sonuc='When picking black berries in the forest, do not give children any berry you are unsure of. In Türkiye, call 114.'),
'guzelavratotu-kopekuzumu': dict(baslik='Deadly nightshade or black nightshade? Two poisonous black berries',
 giris='Deadly nightshade (Atropa belladonna) and black nightshade (Solanum nigrum) are two black-berried plants of the same family. Children eat both thinking they are fruit.',
 fark=['Deadly nightshade berries are large and single; black nightshade berries are small and in clusters.', 'Every part of deadly nightshade is deadly and causes anticholinergic poisoning.', 'Black nightshade’s green berries and leaves contain solanine: nausea, vomiting, diarrhoea, seizures in severe cases.', 'The black nightshade “complex” contains many similar species; identification needs an expert.'],
 sonuc='Neither is eaten. If a child has eaten a wild black berry, take a piece of the plant and call 114.'),
'fitolakka-murver': dict(baslik='How to tell pokeweed from elder',
 giris='Elder (Sambucus nigra) berries are cooked into syrups and jams. The black clusters of pokeweed (Phytolacca americana) look similar and are poisonous.',
 fark=['Pokeweed berries hang on a pink-purple stalk, flattened and segmented; elderberries are small, round and held in an umbrella-shaped cluster.', 'Pokeweed root, mature leaves and seeds are poisonous, and the berries are dangerous especially for children: severe vomiting, bloody diarrhoea and low blood pressure within hours. Deaths have been reported.', 'Elder’s raw berries, leaves and stalks also cause nausea and vomiting; the berries are always cooked.', 'Herbaceous dwarf elder (Sambucus ebulus) is poisonous too.'],
 sonuc='Pick elderberries only from a tree you know, and never eat them uncooked.'),
'fitolakka-yabanmersini': dict(baslik='How to tell pokeweed from bilberry',
 giris='The dark purple-black berries of pokeweed (Phytolacca americana) can be taken for bilberries (Vaccinium myrtillus). One is poisonous, the other an edible forest fruit.',
 fark=['Pokeweed berries hang in clusters on a pink-purple stalk, flattened and segmented; bilberries grow singly on a low shrub.', 'Pokeweed poisoning causes severe vomiting, bloody diarrhoea and low blood pressure within hours; deaths have been reported.', 'Pokeweed root has also poisoned people who took it for ginseng or horseradish.', 'Bilberry has no serious safety concern in its monographs.'],
 sonuc='Do not eat berries that hang on long stalks in clusters and stain purple-red when crushed.'),
'kopekuzumu-yabanmersini': dict(baslik='How to tell black nightshade from bilberry',
 giris='Black nightshade (Solanum nigrum) is a small-berried nightshade of field edges. Its berries can be taken for bilberries (Vaccinium myrtillus).',
 fark=['Black nightshade berries hang in small clusters on a soft herb; bilberries grow on a woody, low forest shrub.', 'Black nightshade’s green berries and leaves contain solanine: nausea, vomiting, abdominal pain, diarrhoea.', 'Its black berry is also confused with deadly nightshade.', 'Bilberries are purple inside; black nightshade berries are greenish inside.'],
 sonuc='A black-berried herb growing in a garden or field edge is not bilberry; do not eat it.'),
'sogut-zakkum': dict(baslik='Willow or oleander? Long, narrow leaves',
 giris='Willow (Salix) bark is the natural ancestor of aspirin. The long, narrow leaves of oleander (Nerium oleander) can be likened to willow and bay leaves, and are deadly.',
 fark=['Oleander leaves are thick, leathery and glossy and grow in whorls of three; willow leaves are thin, soft and alternate.', 'Every part of oleander contains cardiac glycosides; even a few leaves are dangerous.', 'Willow bark is not used by people allergic to aspirin or salicylates, people with asthma or stomach ulcers, in pregnancy or under 18.', 'Using oleander branches as skewers or burning them on a barbecue also causes poisoning.'],
 sonuc='Do not make leaf tea or cut skewers from a branch you are unsure of. In Türkiye, call 114.'),
'gelincik-hashas': dict(baslik='Corn poppy or opium poppy? Two flowers of one genus',
 giris='Corn poppy (Papaver rhoeas) is the red flower of field edges; opium poppy (Papaver somniferum) is the source of opium. They are confused because they belong to the same genus.',
 fark=['Corn poppy is smaller and hairy, with deeply divided leaves. Opium poppy leaves are blue-green and clasp the stem.', 'Corn poppy contains no opium alkaloids; petal tea in small amounts is generally regarded as safe.', 'Opium poppy capsules and latex are addictive and can stop breathing; using it as a home remedy is deadly, especially for children.', 'Corn poppy is also not used by pregnant or breastfeeding women or small children.'],
 sonuc='Use only the red petals for corn poppy tea. Nothing is ever prepared from an opium poppy capsule.'),
'hashas-kaliforniyahashasi': dict(baslik='Is California poppy an opium poppy?',
 giris='No. California poppy (Eschscholzia californica) is in the same family as the opium poppy (Papaver somniferum) but a different genus, and contains no morphine.',
 fark=['California poppy is an orange-flowered garden plant; in Europe it is used as a herbal medicine for sleep and mild tension.', 'Opium poppy capsules and latex are addictive and can stop breathing.', 'California poppy can also impair the ability to drive and use machines.', 'The similar name is their only link; the properties of one do not transfer to the other.',
       'Using opium poppy as a home remedy is fatal, especially in children, and it is legally controlled.'],
 sonuc='California poppy is not a narcotic; the opium poppy is not a home remedy in any form.'),
'guzelavratotu-tatula': dict(baslik='Deadly nightshade or jimsonweed? Two plants, one poison',
 giris='Deadly nightshade (Atropa belladonna) and jimsonweed (Datura stramonium) are two deadly plants of the same family carrying the same tropane alkaloids.',
 fark=['Deadly nightshade has a glossy black berry; jimsonweed a spiny, chestnut-like capsule.', 'With deadly nightshade the greatest danger is children eating the berries; with jimsonweed, teenagers trying it as a “natural drug”.', 'Symptoms are the same: dry mouth, dilated pupils, hot flushed skin, hallucinations, palpitations, coma.', 'These alkaloids are the source of medicines, but in the plant the dose cannot be controlled.'],
 sonuc='Neither has any home use. In Türkiye, call 114 if poisoning is suspected.'),
'banotu-guzelavratotu': dict(baslik='Henbane or deadly nightshade?',
 giris='Henbane (Hyoscyamus niger) and deadly nightshade (Atropa belladonna) are two poisonous plants of the same family carrying the same alkaloids.',
 fark=['Henbane has pale yellow flowers with purple veins; deadly nightshade bell-shaped purple-brown flowers and glossy black berries.', 'Henbane has poisoned people who gathered it with edible wild greens; deadly nightshade berries have been taken for bilberries.', 'A mix-up between deadly nightshade root and burdock root is recorded as fatal in the TİTCK monograph.', 'The symptoms of both are anticholinergic poisoning.'],
 sonuc='When gathering wild greens, stay away from anything that looks like a nightshade. In Türkiye, call 114.'),
'adacayi-tibbiadacayi': dict(baslik='Anatolian sage or common sage?',
 giris='Most sage sold in Türkiye is Anatolian sage (Salvia fruticosa). Europe’s common sage (Salvia officinalis) is a separate species, and the monographs belong to it.',
 fark=['The two species differ in thujone content; Anatolian sage carries less.', 'Common sage essential oil is not taken by mouth; oil equivalent to 15 g of leaf can cause seizures.', 'Neither is drunk long-term or in high doses; neither is recommended in pregnancy, breastfeeding or epilepsy.', 'White sage (S. apiana) is a ritual plant; Spanish sage is thujone-free.'],
 sonuc='Either is fine for a moderate cup of tea; do not drink it every day for months.'),
'amerikanginsengi-ginseng': dict(baslik='American ginseng or Asian ginseng?',
 giris='American ginseng (Panax quinquefolius) and Asian ginseng (Panax ginseng) are separate species of the same genus. On the market, “ginseng” labels often do not name the species.',
 fark=['The WHO and EU monographs belong to Asian ginseng; American ginseng has a TİTCK monograph.', 'American ginseng is not used for more than three months and is stopped seven days before surgery; it may have oestrogenic effects.', 'Both may lower blood sugar and interact with diabetes medicines; Asian ginseng can cause insomnia.', 'Siberian ginseng (Eleutherococcus) is not a ginseng.'],
 sonuc='Check the Latin name on the label: a study of one species is not evidence for the other.'),
'giritkekigi-kekik': dict(baslik='Is dittany of Crete a thyme?',
 giris='In Turkish, “kekik” covers dozens of species from Thymus, Origanum, Thymbra and Satureja. Dittany of Crete (Origanum dictamnus) is one of them and has its own monograph.',
 fark=['Dittany of Crete is a woolly-leaved species native only to Crete; the European monograph covers only this species.', 'The scent and active compound content of “kekik” species differ from one another.', 'Dittany of Crete is used for cough; with breathlessness, high fever or pus in the phlegm, see a doctor.', 'Pure thyme oil is caustic; it is not applied undiluted or swallowed.'],
 sonuc='Which species is sold as “kekik” is often unclear; monograph information applies only to the species named.'),
'kekik-zahter': dict(baslik='Is za’atar (zahter) a thyme?',
 giris='Za’atar (Thymbra spicata) is the everyday spice of Hatay and is also sold under the name “kekik”. Dried, it is hard to tell from other thymes.',
 fark=['The name za’atar covers this plant, Origanum syriacum and the sesame spice blend.', 'Za’atar is rich in carvacrol and smells sharp.', 'Both are safe in kitchen amounts; their essential oils are not taken by mouth or applied undiluted.', 'Za’atar is not used beyond tea amounts in pregnancy; people allergic to the mint family should avoid it.'],
 sonuc='In the kitchen one can stand in for the other; but monograph and study information does not transfer between species.'),
'kekik-mercankosk': dict(baslik='Thyme or sweet marjoram?',
 giris='Sweet marjoram (Origanum majorana) is confused with thyme in name and look. Marjoram smells sweeter, thyme sharper.',
 fark=['Marjoram’s EU monograph covers only O. majorana; blends sold as “thyme” do not replace it.', 'Marjoram ointment is not pushed deep into the nostril; it may reduce the function of the cells that clean the inside of the nose.', 'Neither is used by people allergic to the mint family.', 'Pure thyme oil is caustic; it is not applied undiluted.'],
 sonuc='Both are safe in the kitchen. Look for the Latin name on the product label.'),
'japonnanesi-nane': dict(baslik='Japanese mint or peppermint?',
 giris='Japanese mint (Mentha canadensis) is grown to produce menthol. Peppermint (Mentha × piperita) is a separate species, and the EU monographs belong to it.',
 fark=['Japanese mint oil carries a very high proportion of menthol.', 'Neither oil is applied to the faces or noses of babies and small children; it can cause breathing difficulty.', 'Japanese mint is not drunk in pregnancy, breastfeeding or gallbladder inflammation.', 'Pennyroyal (M. pulegium) is a separate species and is poisonous because of its high pulegone content.'],
 sonuc='Garden peppermint for tea. Keep menthol oils out of children’s reach.'),
'guayusa-mate': dict(baslik='Guayusa or yerba mate? Two caffeinated hollies',
 giris='Guayusa (Ilex guayusa) is the caffeinated leaf tea of the Amazon, mate (Ilex paraguariensis) of the South American plains. Being of the same genus, products can get mixed.',
 fark=['The EU monograph covers only mate; guayusa has none.', 'Both contain caffeine; people with heart rhythm problems, anxiety or insomnia should be careful.', 'Mate is not used with stomach ulcers, high blood pressure, heart rhythm disorders or an overactive thyroid.', 'Holly (Ilex aquifolium), of the same genus, has poisonous berries; it must not be confused with the drink species.'],
 sonuc='Count the daily total of caffeine with coffee and tea.'),
'javazerdecali-zerdecal': dict(baslik='Is Javanese turmeric the same as turmeric?',
 giris='No. Javanese turmeric (Curcuma xanthorrhiza) and turmeric (Curcuma longa) are separate species of the same genus. This is one of the most consequential mix-ups in the catalogue.',
 fark=['Clinical studies of turmeric are not evidence for Javanese turmeric.', 'TİTCK’s monograph also uses the name “curcuma” for Javanese turmeric; checking the Latin name is the only safe way.', 'Javanese turmeric is not used with stomach ulcers, blocked bile ducts, gallstones or liver disease.', 'Cases of liver injury have been reported with high-dose turmeric capsules.'],
 sonuc='If a supplement just says “curcuma”, find out which species it is before using it.'),
'zedoar-zerdecal': dict(baslik='Zedoary or turmeric?',
 giris='Zedoary (Curcuma zedoaria) and turmeric (Curcuma longa) are separate species of the same genus. Zedoary is also sold as “white turmeric”.',
 fark=['Turmeric’s curcumin data do not transfer to zedoary.', 'Zedoary is not used in pregnancy or breastfeeding; it interacts with blood thinners and is stopped before surgery.', 'Turmeric is safe as a spice; liver injury has been reported with high-dose capsules.', 'Galangal (Alpinia) is a separate genus.'],
 sonuc='Turmeric in the kitchen. Zedoary and other “white turmerics” are different plants; their properties do not transfer.'),
'kafuragaci-tarcin': dict(baslik='Camphor tree or cinnamon? Two trees of one genus',
 giris='The camphor tree (Cinnamomum camphora) and cinnamon (Cinnamomum verum, C. cassia) are of the same genus. One is a kitchen spice, the other the source of camphor oil.',
 fark=['Swallowed camphor can cause vomiting, agitation and seizures in children even in small amounts; it is never used under 2.', 'Cinnamon is safe in food amounts; cassia is high in coumarin and can harm the liver if eaten by the teaspoon every day.', 'The camphor tree’s “ho oil” and “ravintsara” chemotypes are camphor-free; read the label.', 'Camphor is not recommended in pregnancy or breastfeeding.'],
 sonuc='Keep camphor oil and camphor rubs out of children’s reach; they are never swallowed.'),
'beyazdut-karadut': dict(baslik='White mulberry or black mulberry?',
 giris='White mulberry (Morus alba) and black mulberry (Morus nigra) are separate species of the same genus. Dark-fruited white mulberry varieties get confused with black mulberry.',
 fark=['Black mulberry fruit is larger and sourer, with a short stalk.', 'White mulberry leaf lowers blood sugar; with diabetes medicine there is a risk of hypoglycaemia, and long-term use causes wind and bloating.', 'Black mulberry may also alter blood sugar and is stopped two weeks before surgery; people allergic to figs should be careful.', 'The fruits are safe as food; care is needed with leaf and bark preparations.'],
 sonuc='Eat the fruit freely. If you use a leaf tea or supplement and take diabetes medicine, ask your doctor first.'),
'aciyonca-kokuluyonca': dict(baslik='Bogbean or sweet clover?',
 giris='Despite both being called “yonca” (clover) in Turkish, bogbean (Menyanthes trifoliata) and sweet clover (Melilotus officinalis) are completely different plants. Sweet clover is a legume; bogbean is not.',
 fark=['Bogbean grows only in wet, boggy places; gathering it in the wild is not advised.', 'Bogbean is not used with stomach or duodenal ulcers.', 'Sweet clover contains coumarin; people on blood thinners and people with liver disease should not use it. Mouldy hay is dangerous.', 'Field clovers (Medicago, Trifolium) are separate genera.'],
 sonuc='Same name, different plant and different warning. Check the Latin name on the label.'),
'antepfistigi-menengic': dict(baslik='Terebinth or pistachio?',
 giris='Terebinth (Pistacia terebinthus) and pistachio (Pistacia vera) are separate species of the same genus. Terebinth coffee is the caffeine-free drink of south-eastern Türkiye.',
 fark=['Terebinth is a wild tree; its fruit, resin and coffee are used.', 'Both are in the cashew family: people allergic to cashew, mango or pistachio may react.', 'Pistachio is a tree nut that can cause severe allergy.', 'Among Pistacia species, the only one with a European Medicines Agency monograph is the mastic tree (P. lentiscus).'],
 sonuc='If you are allergic to cashew or pistachio, do not try terebinth coffee either.'),
'akgunluk-mur': dict(baslik='Frankincense or myrrh? Two incense resins',
 giris='Frankincense (Boswellia) and myrrh (Commiphora myrrha) are two incense resins of the same family, burned for thousands of years; they are separate genera with separate monographs.',
 fark=['In Anatolia the name “günlük” is also given to the sweetgum tree and its resin; that is a different plant.', 'Frankincense is probably safe by mouth; in studies it has been used for up to 6 months.', 'Myrrh is used for mouth and gum inflammation; the tincture must not touch the eyes, and boils on the face should be treated by a doctor.', 'Indian myrrh (guggul) is a separate species; its studies do not apply to myrrh.'],
 sonuc='As incense, both should be burned in a ventilated room, not a closed one.'),
'cayagaci-manuka': dict(baslik='Tea tree or manuka? Two “tea trees”',
 giris='Tea tree (Melaleuca alternifolia, Australia) and manuka (Leptospermum scoparium, New Zealand) are two different plants of the myrtle family; both are sold as “tea tree”.',
 fark=['Tea tree oil is not swallowed or inhaled and is not used undiluted.', 'Manuka oil is not applied neat or taken by mouth either; it is not used in pregnancy or breastfeeding.', 'Manuka honey is very prone to adulteration; look for UMF or MGO certification, and honey is never given to babies under one.', 'The name “tea tree” suggests something drinkable; that is the most dangerous mix-up.'],
 sonuc='Both oils are for external use only, diluted.'),
'cehri-kaskara': dict(baslik='Buckthorn or cascara? Two laxative barks',
 giris='Anatolian buckthorn (Rhamnus) and cascara (Frangula purshiana) are related plants; both contain anthraquinones and act as laxatives.',
 fark=['Buckthorn berries are also used in Anatolia as a dye plant.', 'Fresh cascara bark is emetic; the bark is used after ageing.', 'Neither is used with bowel obstruction, inflammatory bowel disease, in pregnancy, breastfeeding or under 12.', 'Long-term use causes a lazy bowel and salt loss.'],
 sonuc='Anthraquinone laxatives are not used for more than a week. If constipation persists, see a doctor.'),
'kina-kinin': dict(baslik='Henna or cinchona?',
 giris='Their Turkish names are similar (kına, kınakına), but henna (Lawsonia inermis) is a dye plant and cinchona (Cinchona) is the tree that gives quinine.',
 fark=['Henna leaf powder dyes hair and skin; natural henna is generally safe.', 'PPD dye added to so-called “black henna” can cause severe allergy and permanent marks; henna is not used on babies with G6PD deficiency.', 'Cinchona bark or quinine is never used on its own: it can cause ringing in the ears, hearing loss, heart rhythm disorders and blood problems.', 'The amount of quinine in tonic water is very low.'],
 sonuc='Henna for external use; cinchona only as a medicine prescribed by a doctor.'),
'labada-ravent': dict(baslik='Curled dock or rhubarb? Two anthraquinone roots',
 giris='Curled dock (Rumex crispus) and medicinal rhubarb (Rheum palmatum, R. officinale) are two plants of the same family with laxative roots.',
 fark=['Dock leaves are used in cooking; the root can cause vomiting and irritate mucous membranes.', 'The laxative effect of rhubarb root belongs only to the medicinal species; garden rhubarb and ışgın are separate species.', 'Neither is used with bowel obstruction or inflammatory bowel disease; rhubarb is contraindicated in pregnancy, breastfeeding and under 12.', 'Dock is not used with kidney stones or gout.'],
 sonuc='Anthraquinone roots are not used for more than a week.'),
'kavak-sogut': dict(baslik='Poplar or willow? Two salicylate trees',
 giris='Black poplar (Populus nigra) and willow (Salix) are trees of the same family, both carrying salicylates; their barks can be confused.',
 fark=['Willow leaves are longer and narrower.', 'Poplar bud ointment can cause contact dermatitis in people allergic to propolis or Peru balsam.', 'The bark of either is not used by people allergic to aspirin or salicylates or by people with asthma.', 'Willow is not used under 18, especially in feverish viral illness, because of the risk of Reye’s syndrome.'],
 sonuc='Someone who cannot take aspirin cannot use the bark of these two trees either.'),
'gul-kusburnu': dict(baslik='Rose or rose hip? Two products of one genus',
 giris='Rose water and rose oil come from the Isparta oil rose (Rosa damascena); rose hips are the fruit of the dog rose (Rosa canina).',
 fark=['Most garden roses are weakly scented hybrids, not used for oil or rose water.', 'The hairs around rose hip seeds irritate the mouth and gut; always strain.', 'Rose oil is very concentrated; it is not applied undiluted or drunk.', 'Rose water, jam and tea are safe in food amounts.',
       'For rose the EMA does not recommend use under 12, as there is not enough data; its safety in pregnancy and while breastfeeding is not known.'],
 sonuc='Florist roses may be sprayed; buy culinary roses and rose hips from a trusted source.'),
'kizilcik-turnayemisi': dict(baslik='Cornelian cherry or cranberry? A translation error',
 giris='The fruit called “kızılcık” in Türkiye is Cornus mas. The English “cranberry” is Vaccinium macrocarpon, a completely different plant.',
 fark=['On products, cranberry is often wrongly translated into Turkish as “kızılcık”.', 'Cornelian cherry fruit is long with a single stone; the stone is hard, so it is not given whole to small children.', 'Cranberry is used for the urinary tract; a lot of juice can upset the stomach, and sweetened juices raise blood sugar.', 'An interaction with warfarin has been reported for cranberry, but newer studies show no serious effect.',
       'People with a history of kidney stones should avoid high doses of cranberry.'],
 sonuc='If a label says “kızılcık suyu”, check the ingredients for which plant it is.'),
'ayiuzumu-yabanmersini': dict(baslik='Bearberry or bilberry? One Turkish name, two plants',
 giris='In Turkish, “ayı üzümü” can mean both bearberry (Arctostaphylos uva-ursi), used for the urinary tract, and bilberry.',
 fark=['Bearberry leaf is not used for more than a week or more than five times a year, because hydroquinone can harm the liver; not in pregnancy, breastfeeding, under 18 or with kidney disease.', 'Bilberry is a fruit; its monographs report no serious safety concern.', 'Red-fruited lingonberry leaves have dotted undersides; bearberry leaves do not.', 'Bearberry turns the urine green-brown.'],
 sonuc='When buying “ayı üzümü” from a herbalist, ask for the Latin name: one is a medicine, the other a fruit.'),
'aronya-yabanmersini': dict(baslik='Chokeberry or bilberry? Two black berries',
 giris='Chokeberry (Aronia melanocarpa) and bilberry (Vaccinium myrtillus) are two different plants that appear side by side in “black fruit” blends.',
 fark=['Chokeberry is in the rose family, bilberry in the heather family.', 'Chokeberry may lower blood sugar; it is not taken with diabetes medicines or blood thinners.', 'People with rose-family allergy (apple, peach, almond pollen-food syndrome) should not use chokeberry.', 'Bilberry’s high tannin content may cause nausea in sensitive people.'],
 sonuc='Both are eaten as fruit; if you use supplements, discuss your medicines with your doctor.'),
'dereotu-rezene': dict(baslik='Dill or fennel?',
 giris='Dill (Anethum graveolens) and fennel (Foeniculum vulgare) look very alike with fine, hair-like leaves and yellow umbrella flowers; they are separate genera and separate monographs.',
 fark=['Fennel smells clearly of anise; dill’s scent is different.', 'The WHO monograph says dill fruit extracts should not be used in pregnancy or breastfeeding; the leaf is safe in cooking.', 'Because of estragole, fennel is not used long-term in small children or pregnancy.', 'The family includes deadly species such as hemlock; their seeds are not gathered in the wild.'],
 sonuc='Both are safe in the kitchen. If you use the seed for tea, buy it packaged.'),
'frenkkimyonu-rezene': dict(baslik='Caraway or fennel?',
 giris='Caraway (Carum carvi) and fennel (Foeniculum vulgare) are two umbellifers whose fruits get confused when seen together.',
 fark=['Both are recognised in traditional use for bloating and wind.', 'Caraway oil is not taken directly by mouth; it is not used with liver disease or gallstones.', 'Fennel is not used long-term in small children or pregnancy; cross-allergy may occur in people allergic to celery or carrot.', 'Because deadly hemlock is in the same family, their fruits are not gathered in the wild.'],
 sonuc='Either works in a digestive tea; use packaged products.'),
'anason-frenkkimyonu': dict(baslik='Anise or caraway?',
 giris='Anise (Pimpinella anisum) and caraway (Carum carvi) are two umbellifers with small, ribbed fruits.',
 fark=['Anise smells of sweet anethole; caraway is sharper and reminds of rye bread.', 'Both are used for indigestion and bloating.', 'Anise essential oil is not used in pregnancy or children; ask a doctor before giving anise tea to babies.', 'Caraway oil is not taken directly by mouth.',
       'Caraway is not taken by mouth in liver disease, cholangitis, achlorhydria or disorders of the bile ducts.'],
 sonuc='Both are safe for a moderate cup of tea; their essential oils are not drunk.'),
'hatmi-hibiskus': dict(baslik='Marshmallow or hibiscus? Two mallows',
 giris='Marshmallow (Althaea officinalis) and hibiscus (Hibiscus sabdariffa) are of the same family, but their teas are completely different.',
 fark=['Marshmallow root is soaked in cold water to make a slippery drink; it is used for throat irritation and dry cough.', 'Hibiscus tea is made from the fleshy red calyces; it is sour and red.', 'Marshmallow mucilage may delay the absorption of other medicines; leave an hour between them.', 'Hibiscus may strengthen blood-pressure medicines; do not drink a lot in pregnancy.'],
 sonuc='Marshmallow for the throat, hibiscus to cool down. Ornamental hibiscus is not a tea plant.'),
'arpa-bugday': dict(baslik='Barley or wheat? Both contain gluten',
 giris='Barley (Hordeum vulgare) and wheat (Triticum aestivum) were among the first cereals domesticated in the region including Anatolia; their ears look alike.',
 fark=['Barley awns are very long and run the whole length of the ear.', 'Both are forbidden in coeliac disease; barley water, malt extract, malt vinegar and beer also contain gluten.', 'Wheatgrass is gluten-free, but contamination can occur.', 'Einkorn (siyez) and emmer (gernik) are older, hulled wheats.'],
 sonuc='In coeliac disease, wheat, barley and rye are all removed.'),
'feslegen-tulsi': dict(baslik='Basil or tulsi?',
 giris='Kitchen basil (Ocimum basilicum) and India’s holy basil, tulsi (Ocimum tenuiflorum), are separate species of the same genus.',
 fark=['Tulsi leaves are smaller, hairy and clove-scented; Thai “kaprao” is the same species.', 'Basil is safe in food and tea; its essential oil and concentrated supplements are not used in pregnancy or children.', 'Tulsi is not used by people trying to conceive or pregnant women; it may lower blood sugar.', 'Basil leaves are rich in vitamin K; people on warfarin should not suddenly eat large amounts.',
       'Anyone taking blood thinners should stop tulsi before surgery.'],
 sonuc='Basil in the kitchen, tulsi in tea — but avoid tulsi in pregnancy.'),
'mapacho-tutun': dict(baslik='Mapacho or tobacco?',
 giris='Mapacho (Nicotiana rustica) and tobacco (Nicotiana tabacum) are two plants of the same genus. The one used in Amazonian ceremonies is mapacho.',
 fark=['Mapacho carries several times more nicotine than ordinary tobacco; it is not used in the same amounts.', 'High nicotine causes nausea, vomiting, fainting and heart rhythm disorders.', 'Tobacco is addictive and, according to WHO, kills more than 7 million people a year.', 'A child swallowing a cigarette or nicotine liquid is an emergency.'],
 sonuc='Neither has a “safe” use. In Türkiye, call 114 if nicotine is swallowed.'),
'aspir-safran': dict(baslik='Safflower or saffron? “Fake saffron”',
 giris='Safflower (Carthamus tinctorius) is often sold as saffron (Crocus sativus). Saffron is the red stigma of a crocus; safflower the thread-like petals of a daisy-family flower.',
 fark=['Real saffron threads colour water yellow slowly and have their own scent; safflower releases colour at once.', 'Safflower is not used in pregnancy and is contraindicated in bleeding disorders and peptic ulcer.', 'Saffron is safe in food amounts; above 5 g a day it is toxic.', 'Turmeric can also be sold in place of saffron.'],
 sonuc='Very cheap “saffron” is most likely safflower. If you are pregnant, avoid safflower.'),
'arnika-papatya': dict(baslik='Arnica or chamomile?',
 giris='Arnica (Arnica montana) and chamomile (Matricaria chamomilla) are two yellow-and-white flowered plants of the same family; but one is drunk, the other is not.',
 fark=['Arnica is not taken by mouth; it is only applied to the skin as an ointment for bruises and sprains.', 'Herbal arnica ointment is not the same as homeopathic “Arnica 30C”.', 'Chamomile tea is generally safe; it may cause allergy in people allergic to the daisy family.', 'Arnica is also not used by people sensitive to the daisy family.'],
 sonuc='Arnica is not made into tea. Chamomile tea is the mild evening choice.'),

# --- Veri hattı, 24 Kasım 2026: 24 yeni karşılaştırma ---
'porsuk-ardic': dict(baslik='How to tell yew from juniper',
 giris='Yew (Taxus baccata) and juniper (Juniperus species) are both needle-leaved trees that often grow side by side. Juniper berries and twigs have a place in traditional use; yew is highly poisonous and has no antidote.',
 fark=['Yew bears no cone. Its seed sits inside a red, fleshy cup (an aril). Juniper carries blue-purple, cone-like "berries" — this is the clearest single difference.',
       'Yew needles can be mistaken for fir or juniper twigs; when in doubt, look for cones on the branch.',
       'For yew, a lethal dose has been reported at 0.6–1.3 g of leaf per kilogram of body weight; a tea made from 50–100 g of needles is considered fatal.',
       'The fleshy red part of the yew berry is not toxic, but the seed inside it is — a separate danger for children and animals.',
       'Juniper has its own caution: long or high-dose use of the berries can irritate the kidneys. It is not used in pregnancy or kidney disease, and juniper tar is never swallowed.'],
 sonuc='No part of yew is used in folk practice; its needles are raw material for the pharmaceutical industry only. In Türkiye, call 114 (National Poison Centre) or 112 if poisoning is suspected.'),

'mayiselmasi-adamotu': dict(baslik='How to tell mayapple from mandrake',
 giris='Mayapple (Podophyllum peltatum) and mandrake (Mandragora species) are not even related: one is in the Berberidaceae, the other in the Solanaceae. The confusion comes from a name — mayapple is called "American mandrake" in English, after the reputation of its root. Both are high-risk plants.',
 fark=['Mayapple is North American and what is used is the resin of its root and rhizome; mandrake is a Mediterranean plant and what is meant is its root.',
       'In mayapple the root, leaves and unripe fruit are poisonous: severe vomiting, diarrhoea, nerve damage and coma have been reported. Only the flesh of the fully ripe fruit may be eaten in small amounts; the seeds are toxic.',
       'Applying podophyllin resin to the skin carelessly has also caused poisoning.',
       'Every part of mandrake is poisonous; the fruit and root can cause hallucinations, heart-rhythm disturbance and respiratory arrest.',
       'Mandrake roots sold in markets as an aphrodisiac are dangerous.'],
 sonuc='Neither is used as a home remedy. Mayapple must never be used in pregnancy; it can cause birth defects.'),

'salviadivinorum-adacayi': dict(baslik='How to tell diviner’s sage from culinary sage',
 giris='Diviner’s sage (Salvia divinorum) and the sages used in cooking and tea (Salvia officinalis, S. fruticosa) belong to the same genus, but their effects have nothing in common. Sharing a genus name is the only reason they are confused.',
 fark=['Diviner’s sage is a strong psychoactive plant: it causes intense changes in consciousness, loss of coordination and a risk of accidents. Culinary sage has no such effect.',
       'Diviner’s sage is legally controlled in many countries.',
       'In culinary sage the part used is the leaf, brewed as a tea; diviner’s sage is never used in its place.',
       'Culinary sage has its own caution: it contains thujone, so it is not used for long periods or at high doses, and is not recommended in pregnancy, breastfeeding or epilepsy.',
       'Diviner’s sage is not for use in pregnancy, while breastfeeding, by people with mental health conditions, or by anyone on medication.'],
 sonuc='A shared genus name does not make two plants the same. The sage used for tea is Salvia officinalis or S. fruticosa.'),

'frenkkimyonu-dereotu': dict(baslik='How to tell caraway from dill',
 giris='Caraway (Carum carvi) and dill (Anethum graveolens) are two separate genera in the carrot family; in both, the ripe dried fruit and the essential oil are used. Seen side by side, the fruits are hard to tell apart.',
 fark=['Dill leaf is widely used in cooking and known by its smell; in caraway it is the fruit that goes into food.',
       'For dill, pregnancy and breastfeeding are an absolute contraindication in the WHO monograph.',
       'For caraway the barrier is different: liver disease, cholangitis, achlorhydria and disorders of the bile ducts.',
       'Caraway essential oil is not taken undiluted by mouth (TİTCK monograph).',
       'Neither fruit should be gathered from the wild: this family contains lethal species such as poison hemlock.'],
 sonuc='Both are safe as kitchen plants; the difference appears once seed extracts and essential oils are involved.'),

'sahtere-sedef': dict(baslik='How to tell fumitory from rue',
 giris='This confusion is not botanical but nominal: in Turkish, "sedef otu" is used for both fumitory (Fumaria officinalis) and rue (Ruta graveolens). They belong to different families, and rue is markedly riskier.',
 fark=['The Latin name on the label decides — the Turkish name is not enough to tell these two apart.',
       'Touching fresh rue and then going out in the sun can cause severe skin burns (phytophotodermatitis).',
       'Rue can cause miscarriage in pregnancy, and at high doses it is toxic to the liver and kidneys.',
       'Fumitory’s caution is about dose: the TİTCK monograph states that in large amounts it causes severe diarrhoea, muscle cramps and shortness of breath — a concrete reason not to exceed the amount on the label.',
       'For fumitory, bile-duct obstruction, cholangitis and gallstones are barriers to use. Many Fumaria species grow in Türkiye and all are called şahtere; the EU monograph covers only F. officinalis.'],
 sonuc='Of two plants sharing one Turkish name, one is clearly riskier. Do not buy either without a Latin name on the label.'),

'kirlangicotu-gelincik': dict(baslik='How to tell greater celandine from corn poppy',
 giris='Greater celandine (Chelidonium majus) and corn poppy (Papaver rhoeas) are in the same family. Poppy petals are used in small amounts as a tea; taking greater celandine by mouth is a liver problem.',
 fark=['Greater celandine can cause liver damage: the European Medicines Agency found the benefit–risk balance of oral use unfavourable.',
       'The literature describes celandine hepatotoxicity as a distinct form of herb-induced liver injury; cases present with jaundice and raised transaminases.',
       'Greater celandine exudes a yellow latex where it is cut; corn poppy has no such latex.',
       'The Turkish name "sarı sütleğen" confuses greater celandine with the spurges (Euphorbia); both have irritant latex but they are in different families.',
       'Corn poppy’s caution is milder: not for pregnant or breastfeeding women or small children, and not to be combined with sedative medicines.'],
 sonuc='Corn poppy tea in small amounts is generally considered safe. If a product containing greater celandine is used and fatigue or signs of jaundice appear, stop it and see a doctor.'),

'karamuk-altinmuhur': dict(baslik='How to tell barberry from goldenseal',
 giris='Barberry (Berberis vulgaris) and goldenseal (Hydrastis canadensis) are plants from different families, but both contain berberine. The confusion comes from that shared compound and from the name "berberine supplement".',
 fark=['In barberry the part used is the dried stem bark (WHO) and the fruit; in goldenseal it is the root and rhizome.',
       'Goldenseal slows the breakdown of many medicines in the liver (CYP2D6 and CYP3A4) — for anyone on medication this is the real risk.',
       'Goldenseal is not used in pregnancy, while breastfeeding, or in newborns; berberine can worsen jaundice in infants.',
       'For barberry the WHO warning is different: people with high blood pressure, diabetes, glaucoma or a history of cardiovascular disease should be careful, because berberine’s effects on blood pressure and blood sugar can overlap with their medicines.',
       'After applying berberine-containing preparations to the skin, avoid sun and UVA exposure.'],
 sonuc='"Berberine" is a compound, not a plant, and supplements are usually made from neither of these two. Other Berberis species are also collected in Türkiye; the WHO monograph covers only B. vulgaris.'),

'yabanmersini-turnayemisi': dict(baslik='How to tell bilberry from cranberry',
 giris='Bilberry (Vaccinium myrtillus) and cranberry (V. macrocarpon) belong to the same genus and sit side by side on the shelf. Other species in the genus are used for different purposes again.',
 fark=['Cranberry is used for the urinary tract; bilberry is a fruit and a food.',
       'American blueberry (V. corymbosum) is large and pale inside; lingonberry (V. vitis-idaea) is red; the European cranberry (V. oxycoccos) has smaller berries.',
       'Large amounts of cranberry juice cause stomach upset and diarrhoea; sweetened juices raise blood sugar.',
       'People with a history of kidney stones should avoid high doses of cranberry.',
       'An interaction with warfarin has been reported for cranberry; newer studies show no major effect, but INR should be monitored.'],
 sonuc='Four different berries from one genus can be on the same shelf. Which effect you are after decides which Latin name you need.'),

'baloncicegi-ginseng': dict(baslik='How to tell balloon flower from ginseng',
 giris='Balloon flower (Platycodon grandiflorus) is known in Korea as doraji and its root is used. In Korean markets doraji, ginseng and Adenophora roots look alike.',
 fark=['The monograph covers Platycodon only; similar-looking roots do not stand in for it.',
       'Balloon flower is not given by injection — this is the single warning in the WHO monograph: its extracts are markedly haemolytic, that is, they break down red blood cells. Taken by mouth the saponins are not absorbed, so this is not a problem.',
       'Balloon flower depresses the central nervous system; driving and operating machinery are unsafe when it is combined with alcohol or other depressants.',
       'Ginseng’s caution runs the other way: it can cause insomnia.',
       'Garden varieties come in white and pink as well; colour cannot be used to tell species apart.'],
 sonuc='A root that looks similar is not the same plant. Balloon flower and ginseng act in opposite directions.'),

'gumusdugme-papatya': dict(baslik='How to tell feverfew from chamomile',
 giris='Feverfew (Tanacetum parthenium) and chamomile (Matricaria chamomilla) are in the same family and their flowers look alike. Their uses are entirely different — one of the most common visual confusions in the catalogue.',
 fark=['One of feverfew’s old names was Matricaria parthenium, so older sources confuse them too. The Latin name on the label decides.',
       'Mouth ulcers and gastrointestinal complaints have been reported with feverfew (TİTCK).',
       'For both, hypersensitivity to the daisy family is a barrier — this family is large, so people allergic to chamomile, chrysanthemum or sunflower should take care.',
       'Chamomile’s caution is milder: besides allergy, people on blood thinners should be careful.',
       'Chamomile is brewed as flower heads and is an everyday tea; feverfew is not a daily tea plant.'],
 sonuc='A similar flower does not mean a similar use. Feverfew is not brewed in place of chamomile tea.'),

'lotus-gazalboynuzu': dict(baslik='How to tell lotus from bird’s-foot trefoil',
 giris='This confusion comes entirely from a Latin genus name: bird’s-foot trefoil is Lotus corniculatus, but the plant people mean by "lotus" is Nelumbo nucifera, an aquatic plant. The two have nothing to do with each other.',
 fark=['Lotus (Nelumbo nucifera) is an aquatic plant; its root, seed, leaf and flower are used and it is safe as food.',
       'Bird’s-foot trefoil (Lotus corniculatus) is a legume that grows in meadows.',
       'Bird’s-foot trefoil carries cyanogenic glycosides (linamarin, lotaustralin). The amount varies from plant to plant by inheritance, so there is no answer to "how much is safe" for a herbal tea — it is not recommended as a drink.',
       'Lotus root is not eaten raw; as an aquatic plant it can carry parasites.',
       'The water lilies of Türkiye’s lakes (Nymphaea, Nuphar) are a third group: water lily leaves lie on the surface, while lotus leaves and flowers rise above the water.'],
 sonuc='Sharing a genus name is not kinship. For tea, "lotus" means Nelumbo; the yellow meadow flower is Lotus corniculatus and is not drunk.'),

'yulaf-bugday': dict(baslik='How to tell oat from wheat',
 giris='Oat (Avena sativa) and wheat (Triticum aestivum) are two cereals from the same family. For coeliac disease the difference is not the species but cross-contamination — and that is the point most often missed.',
 fark=['Pure oat contains no gluten, but oats are grown in the same fields, milled in the same mills and processed in the same plants as wheat and barley. An oat product without a "gluten free" label cannot be considered safe for someone with coeliac disease.',
       'The TİTCK monograph is explicit: people with coeliac disease should not use oats. The EU monograph puts it more softly, but for the same reason.',
       'With wheat the position is clear: wheat contains gluten and is excluded in coeliac disease. Wheatgrass contains no gluten but can be contaminated.',
       'Oat grain and oat straw are two different drugs with separate indications; using one in place of the other goes against the monograph.',
       'People with disorders of the oesophagus, stomach or bowel are advised not to use oats.'],
 sonuc='The problem with oats is not in the plant but in the plant floor. In coeliac disease, only oat products labelled gluten free are used.'),

'ucgul-kokuluyonca': dict(baslik='How to tell red clover from sweet clover',
 giris='In Turkish the word "yonca" covers three separate genera: red clover (Trifolium), sweet clover (Melilotus) and bogbean (Menyanthes). Three different plants, three different uses, three different safety profiles.',
 fark=['Sweet clover’s real risk comes from its coumarin chemistry: it is not used by people on anticoagulants or by anyone with current or past liver disease. These two rules in the TİTCK monograph belong together, because clotting factors are made in the liver in a vitamin K–dependent way.',
       'With sweet clover the most important practical point is not the species but the condition: mouldy hay is dangerous and should not be used as animal feed either.',
       'Red clover’s contraindications are hormonal: it is not used by people with hormone-dependent disease, oestrogen-dependent cancer or a family history of it; not in protein S deficiency; and it is stopped two weeks before surgery.',
       'Red clover is not used under 12, in pregnancy or while breastfeeding. That grazing animals eat a plant does not make it safe as a supplement.',
       'White-flowered Melilotus albus grows alongside sweet clover in Türkiye and looks very similar; the EU monograph covers only M. officinalis.'],
 sonuc='Three genera sharing one common name have completely different safety profiles. Look for the Latin name on the label.'),

'ucgul-aciyonca': dict(baslik='How to tell red clover from bogbean',
 giris='Bogbean (Menyanthes trifoliata) is confused with red clover (Trifolium) above all because its species name contains "trifoliata" — yet it is not a Trifolium, nor even in the same family.',
 fark=['Habitat is the distinguishing feature: bogbean grows only in wet ground and peat bogs. Red clover is found in dry meadows.',
       'Bogbean works through its bitter taste, stimulating gastric secretion; for that reason it is not used by people with an active stomach or duodenal ulcer — both the EU and TİTCK monographs say so.',
       'Red clover’s barriers are hormonal: a history of oestrogen-dependent cancer, hormone-dependent disease, protein S deficiency; and it is stopped two weeks before surgery.',
       'Gathering bogbean from the wild is not recommended; a pharmacy product should be preferred.',
       'Reported side effects of red clover include rash-like reactions, muscle pain, headache and nausea.'],
 sonuc='"Trifoliata" in a species name shows no kinship. A "clover" found in wet ground is bogbean, and it is not gathered.'),

'gazalboynuzu-kokuluyonca': dict(baslik='How to tell bird’s-foot trefoil from sweet clover',
 giris='Both are legumes, both have yellow flowers, and both grow together in meadows. The name "sarı yonca" (yellow clover) is used locally for either, but their chemistry and their risks differ.',
 fark=['Bird’s-foot trefoil carries cyanogenic glycosides (linamarin, lotaustralin), and the amount varies from plant to plant by inheritance. There is therefore no answer to "how much is safe" in a herbal tea, and it is not recommended as a drink.',
       'Sweet clover’s risk is coumarin: it is not used by people on anticoagulants or with liver disease.',
       'With sweet clover, mouldy hay is a separate and serious danger; it should not be used as animal feed either.',
       'For bird’s-foot trefoil, the amount of fresh herbage is kept moderate in animal feeding.',
       'The Latin name of bird’s-foot trefoil is Lotus corniculatus and it has nothing to do with the "lotus" (Nelumbo nucifera) in the catalogue.'],
 sonuc='Both are familiar meadow plants and both are problematic as tea — for different reasons.'),

'ballibaba-aslankuyrugu': dict(baslik='How to tell white dead-nettle from motherwort',
 giris='White dead-nettle (Lamium album) and motherwort (Leonurus cardiaca) are separate genera in the same family. The confusion is old: one of motherwort’s former names was Lamium cardiaca.',
 fark=['The leaf tells them apart: motherwort has deeply divided leaves with pointed lobes, white dead-nettle heart-shaped, toothed ones.',
       'Motherwort is contraindicated in pregnancy — and this is an important distinction in the catalogue: where the EU monograph says for most plants "not recommended, as data are insufficient", for this one it says plainly that it is not used in pregnancy.',
       'For motherwort the EU monograph states that the ability to drive and use machines may be impaired.',
       'For white dead-nettle there is no record of serious toxicity or side effects, but there is no human safety data either — so there is no basis for regular use in pregnancy, breastfeeding or children.',
       'In Turkish, "aslan kuyruğu" is also used for Leonotis leonurus, grown as an ornamental; that is a different genus.'],
 sonuc='Leaf shape separates them. In motherwort the pregnancy rule is firm; in white dead-nettle there is an absence of data — the two are not the same thing.'),

'ballibaba-isirgan': dict(baslik='How to tell white dead-nettle from nettle',
 giris='White dead-nettle (Lamium album) has leaves resembling stinging nettle (Urtica dioica) and the two are often confused in the field. The most practical difference is felt by touch: white dead-nettle does not sting.',
 fark=['White dead-nettle has large, two-lipped flowers; nettle’s flowers are small and hang in greenish clusters.',
       'Even when mistaken for nettle, white dead-nettle does not sting — it has no stinging hairs.',
       'There is no human safety data for white dead-nettle: no basis for regular use in pregnancy, breastfeeding or children, so it is not recommended as a habit.',
       'Allergy is possible within the mint family; people sensitive to it should take care.',
       'Purple dead-nettle (Lamium purpureum) is a separate species in the same genus.'],
 sonuc='If it does not sting, it is not nettle. White dead-nettle looks harmless, but there is no data supporting regular use.'),

'kagitcicegi-olmezcicek': dict(baslik='How to tell immortelle from sandy everlasting',
 giris='The confusion comes from English: both are called "everlasting flower". Sandy everlasting (Helichrysum arenarium) has a TİTCK monograph; immortelle (Xeranthemum annuum) does not.',
 fark=['Two cyanogenic compounds have been isolated from Xeranthemum. Cyanogenic glycosides can release cyanide when chewed or soaked; the amounts in this plant and the effect of preparation method are unknown — so it is not recommended as a drink.',
       'Sandy everlasting can stimulate bile secretion, so it is not used in bile-duct obstruction, gallstones, liver disease or cholangitis.',
       'Both are in the daisy family; people sensitive to it may have allergic reactions.',
       'The "paper flower" sold by florists is sometimes Xerochrysum bracteatum, an Australian strawflower — a third species.',
       'Helichrysum italicum, grown around the Mediterranean, is sold in cosmetics and as an essential oil and is a different species again; the EU monograph covers only H. arenarium.'],
 sonuc='One English name covers two separate genera. If it is to be drunk, look for the species that has a monograph.'),

'esekotu-cuhacicegi': dict(baslik='How to tell evening primrose from cowslip',
 giris='This confusion is nominal: "çuha çiçeği" is the Turkish name of the genus Primula, not of evening primrose (Oenothera biennis). The English name "evening primrose" was carried into Turkish incorrectly.',
 fark=['In evening primrose what is used is the fixed oil pressed from the seeds; in cowslip it is the root and the flower.',
       'People with epilepsy do not use evening primrose (TİTCK) — there is an old concern that the oil may lower the seizure threshold, and the monograph records it as an absolute contraindication.',
       'Evening primrose should be stopped two weeks before surgery; interactions with anticoagulants have been reported.',
       'For cowslip, people sensitive to the active substance or to other Primula species do not use it — the ornamental Primula obconica is a known source of contact allergy.',
       'For cowslip, careful use is advised in gastritis or stomach ulcer. In Turkish, "akşam sefası" is also used for Mirabilis jalapa, another plant entirely.'],
 sonuc='When buying, look for the Latin name (Oenothera) and the words "seed oil". Cowslip is a different plant.'),

'yabanyasemini-kusburnu': dict(baslik='How to tell bittersweet nightshade from rosehip',
 giris='The red berries of bittersweet nightshade can be mistaken for edible fruit — rosehip above all. Bittersweet nightshade is poisonous.',
 fark=['Rosehip is the fruit of the wild rose (Rosa canina) and sits on the thorny branches of a rose bush.',
       'The berries of bittersweet nightshade are poisonous; the stem drug should be bought as a pharmacy product.',
       'Black nightshade (Solanum nigrum) is the black-fruited relative of bittersweet nightshade, and it is poisonous too.',
       'Rosehip’s own caution is mild: the hairs around the seeds irritate the mouth and bowel, so it should not be consumed unstrained.',
       'A red berry on its own is no sign of edibility; look at the whole plant.'],
 sonuc='Do not gather a berry just because it is red. In Türkiye, call 114 or 112 if poisoning is suspected.'),

'yabanyasemini-frenkuzumu': dict(baslik='How to tell bittersweet nightshade from blackcurrant',
 giris='The red berries of bittersweet nightshade can be mistaken for currants. Blackcurrant (Ribes nigrum) is a food and a drug with a monograph; bittersweet nightshade is poisonous.',
 fark=['Currant berries hang in drooping clusters, even in size and glossy; bittersweet nightshade does not form such a regular cluster.',
       'The berries of bittersweet nightshade are poisonous.',
       'In blackcurrant the monograph covers the leaf; fruit, syrup and seed-oil products fall outside it.',
       'In Turkish, "frenk üzümü" also covers redcurrant (Ribes rubrum) and gooseberry (Ribes uva-crispa); the monograph covers only the black species.',
       'Blackcurrant leaf is not used in serious heart or kidney disease where fluid intake is restricted; joint pain with swelling, redness or fever should be assessed by a doctor.'],
 sonuc='The regularity of the cluster is the first sign, but certainty comes from looking at the whole plant. When in doubt, do not gather.'),

'altinbasak-javacayi': dict(baslik='How to tell goldenrod from Java tea',
 giris='This confusion comes from a translation error: in the English-name line of the TİTCK monograph, goldenrod is given as "Java tea" — but Java tea is Orthosiphon aristatus, an entirely different plant.',
 fark=['Goldenrod is in the daisy family; Java tea is in the mint family. What they share is that both are used to flush the urinary tract.',
       'Neither is used in serious heart or kidney disease where fluid intake must be restricted — the flushing indication requires drinking plenty of water.',
       'For goldenrod, hypersensitivity to the daisy family is a separate barrier.',
       'Java tea is not recommended under 18, in pregnancy or while breastfeeding.',
       'Goldenrod has a second confusion of its own: the North American Solidago canadensis and S. gigantea have naturalised in Türkiye, look very like goldenrod and often grow mixed with it; the EU monograph covers only S. virgaurea.'],
 sonuc='The name "Java tea" has stuck to two different plants. With either, fever, painful urination or blood in the urine means seeing a doctor.'),

'minecicegi-melisa': dict(baslik='How to tell vervain from lemon balm',
 giris='The confusion arises among the names of lemon-scented plants. The EMA monograph "Verbenae citriodorae folium" is for lemon verbena (Aloysia citrodora) — neither for vervain (Verbena officinalis) nor for lemon balm (Melissa officinalis).',
 fark=['No regulatory body has carried out a safety assessment of vervain; with no safety data, it is not used in pregnancy, while breastfeeding, or in children.',
       'Lemon balm is generally safe; the one point to watch is people taking thyroid medication.',
       'Vervain is in the vervain family, lemon balm in the mint family — separate families.',
       'Lemon verbena (Aloysia citrodora) is a third plant and the one the monograph belongs to; it should not be confused with vervain.',
       'The colourful "verbenas" sold as bedding plants are other species again.'],
 sonuc='A lemon scent is not a plant identity. For tea, lemon balm; for a product with a monograph, lemon verbena — vervain is neither.'),

'mucura-ajosacha': dict(baslik='How to tell anamu from ajo sacha',
 giris='Anamu (Petiveria alliacea) smells of garlic when crushed and so can be confused with ajo sacha (Mansoa alliacea). Both are Amazonian plants, they belong to different families, and for both the human safety data are insufficient.',
 fark=['In anamu the parts used are the leaf and root; in ajo sacha the leaf, stem and root.',
       'The safety of neither has been adequately studied in humans.',
       'Anamu is not used in pregnancy; ajo sacha is not used in pregnancy, while breastfeeding, or in children.',
       'In northern Peruvian markets, Cordia alliodora may also be sold under the name ajo sacha — a third plant.',
       'The garlic smell is shared by all three, so smell is not a distinguishing feature; look at the family and the leaf shape.'],
 sonuc='A garlic smell is not an identity. Safety data are insufficient for both plants, and a market name cannot be relied on.'),
}
